/* Ley de Transporte Terrestre — Gaceta Oficial N° 38.985 del 1° de agosto de 2008.
   Transcripción fiel del documento fuente (págs. 363.052 a 363.067). */
window.LEY_DATA = {
  meta: {
    titulo: "Ley de Transporte Terrestre",
    gaceta: "Gaceta Oficial de la República Bolivariana de Venezuela N° 38.985",
    fecha: "Viernes 1° de agosto de 2008",
    sancion: "Dada, firmada y sellada en el Palacio Federal Legislativo, sede de la Asamblea Nacional, en Caracas, a los ocho días del mes de julio de dos mil ocho.",
    descripcion: "La presente Ley tiene por objeto la regulación del transporte terrestre, a los fines de garantizar el derecho al libre tránsito de personas y de bienes por todo el territorio nacional, la realización de la actividad económica del transporte y de sus servicios conexos, por vías públicas y privadas de uso público, así como lo relacionado con la planificación, ejecución, gestión, control y coordinación de la conservación, aprovechamiento y administración de la infraestructura, todo lo cual conforma el Sistema Nacional de Transporte Terrestre."
  },
  items: [
    { t: "titulo", num: "I", nombre: "De las Disposiciones Fundamentales" },
    { t: "art", n: 1, ep: "Objeto", b: [
      { p: `La presente Ley tiene por objeto la regulación del transporte terrestre, a los fines de garantizar el derecho al libre tránsito de personas y de bienes por todo el territorio nacional, la realización de la actividad económica del transporte y de sus servicios conexos, por vías públicas y privadas de uso público, así como lo relacionado con la planificación, ejecución, gestión, control y coordinación de la conservación, aprovechamiento y administración de la infraestructura, todo lo cual conforma el Sistema Nacional de Transporte Terrestre.` },
      { p: `Quedan exceptuados de la presente Ley los transportes sobre rieles que se rigen por sus leyes especiales.` }
    ]},
    { t: "art", n: 2, ep: "Finalidad del Sistema", b: [
      { p: `El Sistema Nacional de Transporte Terrestre tiene como finalidad ordenar, transformar y orientar el sector hacia su pleno desarrollo. Asimismo, la ejecución de la infraestructura que se requiere para operarlo de manera eficiente y la coordinación de los órganos competentes del Poder Público, en la rectoría, planificación y ejecución de los procedimientos para el control del transporte terrestre.` }
    ]},
    { t: "art", n: 3, ep: "Naturaleza del régimen del transporte terrestre", b: [
      { p: `El régimen del transporte terrestre previsto en la presente Ley, constituye una actividad de interés social, pública, económica y estratégica a cuya realización concurren el Estado, los ciudadanos y ciudadanas, la sociedad organizada y los y las particulares, de conformidad con la ley.` }
    ]},
    { t: "art", n: 4, ep: "De la distribución de las competencias", b: [
      { p: `La regulación del transporte terrestre corresponde a los organismos competentes en esta materia. La competencia se distribuye entre el Poder Público Nacional, Estadal y Municipal.` }
    ]},
    { t: "art", n: 5, ep: "De la competencia del Poder Público Nacional", b: [
      { p: `Es de la competencia del Poder Público Nacional, en materia de transporte terrestre, lo relacionado con licencias de conducir, el Registro Nacional de Vehículos y de Conductores y Conductoras, tipología de unidades de transporte, condiciones de carácter nacional para la prestación de los servicios de transporte de uso público y de uso privado de personas, el transporte terrestre público de pasajeros y pasajeras en rutas suburbanas e interurbanas, sin menoscabo de las competencias que la ley y los reglamentos atribuyan a los municipios o gobiernos metropolitanos, el transporte de carga, la circulación en el ámbito nacional, el régimen sancionatorio, el control y fiscalización del tránsito en la vialidad, sin perjuicio de las competencias de los estados y municipios, los servicios conexos de carácter nacional, los procedimientos por accidentes de tránsito, las normas técnicas y administrativas para la construcción, mantenimiento y gestión de la vialidad, así como la actuación en el otorgamiento de concesiones, el ordenamiento de las estaciones de peajes, el establecimiento de las tarifas en el ámbito nacional y las demás que le atribuya la ley.` }
    ]},
    { t: "art", n: 6, ep: "De la competencia del Poder Público Estadal", b: [
      { p: `Es de la competencia del Poder Público Estadal, en materia de transporte terrestre, la conservación, administración y aprovechamiento de las carreteras y autopistas nacionales, en coordinación con el Poder Público Nacional, el servicio de transporte terrestre público y terminales de pasajeros y pasajeras interurbanos de carácter estadal, la ejecución, conservación, administración, aprovechamiento y el control de la circulación de las vías terrestres estadales y el destino de las multas impuestas, de conformidad con lo previsto en esta Ley.` }
    ]},
    { t: "art", n: 7, ep: "De la competencia del Poder Público Municipal", b: [
      { p: `Es de la competencia del Poder Público Municipal, en materia de transporte terrestre, la prestación del servicio de transporte terrestre público urbano y el establecimiento de zonas terminales y recorridos urbanos, para el transporte suburbano e interurbano de pasajeros y pasajeras con origen y destino dentro de los límites de su jurisdicción, bajo las normas de carácter nacional aplicables, así como las condiciones de operación de los servicios de transporte terrestre público y privado en el ámbito de su jurisdicción; la ingeniería de tránsito para la ordenación de la circulación de vehículos y personas de acuerdo con las normas de carácter nacional; las autorizaciones o permisos de vehículos a tracción de sangre; la construcción y mantenimiento de la vialidad urbana; los servicios conexos; el destino de las multas impuestas de conformidad con lo previsto en esta Ley; el control y fiscalización de tránsito, según la normativa de carácter nacional y las demás que por su naturaleza le sean atribuidas. Cualquier restricción de circulación que los municipios deseen aplicar debe ser evaluada y aprobada por el ministerio del poder popular con competencia en materia de transporte terrestre.` }
    ]},
    { t: "art", n: 8, ep: "Destinatarios del Sistema Nacional de Transporte Terrestre", b: [
      { p: `Son destinatarios del Sistema Nacional de Transporte Terrestre los peatones, pasajeros y pasajeras, conductores y conductoras, usuarios y usuarias, y, operadores y operadoras del servicio de transporte terrestre público y privado, sus actividades conexas, y las personas de movilidad reducida con las condiciones especiales que debe tener el Sistema Nacional de Transporte Terrestre que facilite su desplazamiento.` }
    ]},
    { t: "art", n: 9, ep: "Del Registro", b: [
      { p: `El Instituto Nacional de Transporte Terrestre, llevará el Registro del Sistema Nacional de Transporte Terrestre, el cual comprende: vehículos, conductores y conductoras, infraestructura, servicios conexos de transporte terrestre, accidentes, infracciones y sanciones y estará a cargo del Registrador o Registradora y de los Registradores o Registradoras Delegados y Delegadas en cada entidad federal.` }
    ]},
    { t: "art", n: 10, ep: "Del Registro de accidentes, infracciones y sanciones", b: [
      { p: `El Registro de accidentes, infracciones y sanciones a que se refiere esta Ley, será llevado por el Instituto Nacional de Transporte Terrestre, a través del Cuerpo Técnico de Vigilancia del Transporte Terrestre.` },
      { p: `En todo caso, las demás autoridades competentes que realicen procedimientos relacionados con accidentes, infracciones y sanciones, deben remitir la información al Instituto, de conformidad con las normas y procedimientos establecidos en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 11, ep: "De los demás registros locales y regionales", b: [
      { p: `Las autoridades municipales, metropolitanas y estadales, deberán llevar los registros actualizados del Sistema Nacional de Transporte Terrestre, sus servicios conexos, dentro de su respectiva jurisdicción y competencia, los cuales deben remitirse al Instituto Nacional de Transporte Terrestre a fin de mantener actualizada una base de datos confiable, cuyas características, en cuanto al formato, contenido, reporte y cualquier otro elemento que sirva de apoyo para su elaboración y permanencia, se establecerá en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 12, ep: "Del transporte internacional", b: [
      { p: `El servicio de transporte terrestre internacional de personas y de carga se regirá por los acuerdos, convenios y tratados internacionales, suscritos por la República Bolivariana de Venezuela y por las disposiciones contenidas en la presente Ley y su Reglamento.` }
    ]},
    { t: "art", n: 13, ep: "Principios del Sistema Nacional de Transporte Terrestre", b: [
      { p: `El Sistema Nacional de Transporte Terrestre debe responder a los principios de actividad sustentable, a la mejora de la calidad de vida de los ciudadanos y las ciudadanas, a la disminución de la contaminación ambiental, a garantizar el buen trato a los usuarios y las usuarias, la seguridad y comodidad en los servicios de transporte terrestre público y la participación ciudadana, orientada a satisfacer las necesidades y requerimientos de la movilidad y accesibilidad en todos los ámbitos de la vida ciudadana.` }
    ]},
    { t: "art", n: 14, ep: "Derechos de los usuarios y las usuarias", b: [
      { p: `Los usuarios y las usuarias de las vías públicas de uso permanente o casual, tienen derecho a circular libremente, en condiciones idóneas de transitabilidad y seguridad y serán resarcidos por quienes tengan la responsabilidad de administrarla, por los daños personales y materiales imputados al mal estado de la vialidad.` }
    ]},
    { t: "art", n: 15, ep: "Deberes de los usuarios y las usuarias", b: [
      { p: `Los usuarios y las usuarias están obligados y obligadas a cumplir con la normativa que rige el transporte terrestre, así como pagar la contraprestación respectiva, si la hubiere, por la utilización del tramo de las vías administradas.` }
    ]},
    { t: "titulo", num: "II", nombre: "De las Autoridades Administrativas" },
    { t: "cap", num: "I", nombre: "Disposiciones Generales" },
    { t: "art", n: 16, ep: "Autoridades administrativas", b: [
      { p: `Las autoridades administrativas del transporte terrestre, a nivel nacional, son el ministerio del poder popular con competencia en materia de transporte terrestre y el Instituto Nacional de Transporte Terrestre; y a nivel estadal, municipal son las gobernaciones, alcaldías municipales y metropolitanas, por intermedio de sus entes administrativos competentes, en el ámbito de sus respectivas jurisdicciones.` }
    ]},
    { t: "art", n: 17, ep: "Del órgano rector", b: [
      { p: `El Ejecutivo Nacional, por órgano del ministerio del poder popular con competencia en materia de transporte terrestre, es el órgano rector del transporte terrestre, y le corresponde la elaboración de las políticas, estrategias, planes nacionales, sectoriales y normas generales que regulan la actividad del Sistema Nacional de Transporte Terrestre, en consulta con los sectores involucrados.` },
      { p: `Cualquier materia relacionada con el transporte terrestre que sea competencia de otros entes del Ejecutivo Nacional, Estadal o Municipal debe estar en concordancia con los lineamientos del ministerio del poder popular con competencia en materia de transporte terrestre.` }
    ]},
    { t: "art", n: 18, ep: "Órganos de ejecución", b: [
      { p: `A los efectos de esta Ley, se entiende por órganos de ejecución las autoridades encargadas de realizar y verificar el control del Sistema Nacional de Transporte Terrestre, los cuales son:` },
      { ol: [
        `El Cuerpo Técnico de Vigilancia del Transporte Terrestre, bajo la supervisión y adscripción del Instituto Nacional de Transporte Terrestre.`,
        `Los cuerpos de policías: nacional, municipales y estadales debidamente homologados que, conforme a esta Ley, tengan dentro de sus funciones el control de la operación del transporte terrestre.`,
        `La Fuerza Armada Nacional, que podrá actuar como órgano ejecutor de la presente Ley, sin perjuicio de las funciones que deban realizar los organismos policiales y de ejecución anteriormente indicados.`
      ]}
    ]},
    { t: "art", n: 19, ep: "Control de la circulación del tránsito", b: [
      { p: `El Cuerpo Técnico de Vigilancia del Transporte Terrestre, al igual que todos los órganos ejecutores, tienen la rectoría para el control de la circulación del tránsito, del transporte de personas y de carga, en las carreteras y autopistas o vías expresas nacionales, aún cuando atraviesen zonas urbanas, incluyendo dentro de éstas los distribuidores y sus ramales principales de interconexión de alta velocidad y ocupación vehicular que se encuentren conexos con el Sistema de Vialidad Nacional. Igualmente, podrá inspeccionar los estacionamientos autorizados para guarda y custodia de vehículos, y demás atribuciones, de conformidad con esta Ley y su Reglamento.` }
    ]},
    { t: "art", n: 20, ep: "Homologación de las policías", b: [
      { p: `Las policías que tengan a su cargo el control y vigilancia de tránsito, en su respectiva vialidad, distinta a la nacional, podrán asumir la fiscalización de las vías de su competencia, aplicando la legislación nacional.` },
      { p: `Las policías podrán actuar en el levantamiento de accidentes de tránsito con daños materiales, siempre que los funcionarios hayan sido homologados por el Instituto Nacional de Transporte Terrestre, conforme con lo establecido en el Reglamento de esta Ley.` },
      { p: `Son nulas las actuaciones de los policías que no hayan sido homologados según lo dispuesto en este artículo.` }
    ]},
    { t: "art", n: 21, ep: "Carácter excepcional de la Fuerza Armada Nacional", b: [
      { p: `La Fuerza Armada Nacional ejercerá excepcionalmente funciones especiales de autoridad administrativa, competente para el control y vigilancia del tránsito en la red vial.` }
    ]},
    { t: "cap", num: "II", nombre: "Del Instituto Nacional de Transporte Terrestre" },
    { t: "art", n: 22, ep: "Instituto Nacional de Transporte Terrestre", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es un ente adscrito al ministerio del poder popular con competencia en materia de transporte terrestre, con personalidad jurídica, que goza de los privilegios y prerrogativas que se le acuerdan a la República, de conformidad con la ley, y tendrá su sede en la ciudad de Caracas, sin perjuicio de que pueda establecerla en cualquiera otra localidad del país.` },
      { p: `El Instituto Nacional de Transporte Terrestre establecerá las oficinas y dependencias regionales que permitan la optimización de los servicios de transporte terrestre que presta.` },
      { p: `Parágrafo Único: El Instituto Nacional de Transporte Terrestre formará parte del Sistema Nacional de Protección Civil, garantizando la integración, articulación y coordinación de acciones de prevención y atención entre los órganos del Poder Público Nacional, Estadal y Municipal, ante la ocurrencia de eventos con efectos adversos que se derivan de los accidentes de tránsito terrestre.` }
    ]},
    { t: "art", n: 23, ep: "Atribuciones del Instituto Nacional de Transporte Terrestre", b: [
      { p: `Son atribuciones del Instituto Nacional de Transporte Terrestre:` },
      { ol: [
        `La planificación y ejecución de programas de fortalecimiento institucional del sector transporte terrestre.`,
        `Llevar el Registro del Sistema Nacional de Transporte Terrestre.`,
        `Registro, expedición, renovación y control de licencias para conducir vehículos a motor, en el ámbito nacional, en los diferentes grados y categorías.`,
        `Registro, expedición y control de títulos profesionales para conducir vehículos a motor con fines de lucro.`,
        `Otorgamiento, registro y control de placas identificadoras de vehículos a motor destinadas al uso público o privado, en las diferentes clasificaciones y modalidades.`,
        `Los permisos y registro de los servicios de transporte terrestre público y privado, así como la regulación y control del transporte terrestre público de pasajeros y pasajeras, y de carga, en el ámbito de la competencia nacional.`,
        `Estudios de proyectos, otorgamiento de permisos, regulación y registro de los servicios conexos de carácter nacional, como terminales públicos y privados, paradores viales de pasajeros y pasajeras, turísticos y de carga, terminales generadores de transferencia e intermodal de carga, transporte de encomienda, escuelas del transporte, estacionamientos concesionarios del Instituto, estaciones fijas y móviles de revisión técnica, mecánica y física de vehículos; ubicación y acceso de las estaciones de servicios, servicios de grúas de arrastre y de plataforma y cualquier otro, de conformidad con el ordenamiento jurídico.`,
        `Estudio y revisión de tarifas y fletes del transporte terrestre público de pasajeros y pasajeras, y de carga, en los casos previstos en la ley.`,
        `Todo lo concerniente a la planificación, funcionamiento y control de los recursos del Instituto y de sus órganos desconcentrados.`,
        `Estadísticas del transporte terrestre y dispositivos para el control del tránsito.`,
        `Promover la educación y seguridad vial.`,
        `Establecer los criterios técnicos y otorgar los permisos para la colocación de vallas y demás medios publicitarios en las vías públicas nacionales y en los predios colindantes a las mismas, el control de su ubicación y los procedimientos administrativos para su remoción, en coordinación con las autoridades estadales y municipales.`,
        `Establecer los criterios técnicos y otorgar los permisos para la colocación de publicidad en los vehículos.`,
        `Velar por el cumplimiento de las normas relativas a la circulación y seguridad en el ámbito nacional.`,
        `Establecer los mecanismos de coordinación y homologación de las policías con competencia para el control y vigilancia del tránsito y transporte terrestre.`,
        `Otorgar las autorizaciones para la prestación de los servicios de transporte terrestre público de pasajeros y pasajeras, y de carga en el ámbito de la competencia nacional.`,
        `Otorgar las autorizaciones para los trabajos sobre la infraestructura vial en el ámbito de la competencia nacional.`,
        `Aplicar las sanciones administrativas, en los casos previstos en esta Ley.`,
        `Velar por el correcto funcionamiento en la prestación del servicio de transporte terrestre.`,
        `Percibir y administrar los ingresos provenientes de los servicios que preste y de las sanciones que imponga.`,
        `Dictar actos administrativos generales o particulares, en las materias de su competencia. Estos actos agotan la vía administrativa y los interesados podrán acudir directamente ante la jurisdicción contencioso administrativa.`,
        `Informar trimestralmente al ministerio del poder popular con competencia en materia de transporte terrestre sobre los ingresos que perciba y administre.`,
        `Controlar y regular la colocación, conservación y mantenimiento de la señalización y demarcación de las vías, así como la autorización para la colocación y señalización de los mecanismos de control de velocidad en las carreteras de vías nacionales.`,
        `Otorgar en materia de terminales públicos y privados la certificación del proyecto, en cuanto al cumplimiento de las normas técnicas correspondientes, así como el registro del servicio una vez otorgada la licencia de operación.`,
        `Otorgar la licencia de operación de servicio conexo cuando se trate de operadores u operadoras sujetos o sujetas a la competencia nacional.`,
        `El control, inspección y supervisión de los terminales públicos y privados que integran el Sistema Nacional de Terminales de Pasajeros y Pasajeras, del Transporte Terrestre Público y Privado.`,
        `Las demás que se le asignen o le confiera esta Ley.`
      ]}
    ]},
    { t: "art", n: 24, ep: "Patrimonio del Instituto Nacional de Transporte Terrestre", b: [
      { p: `El patrimonio del Instituto Nacional de Transporte Terrestre está constituido por:` },
      { ol: [
        `Todos aquellos bienes muebles e inmuebles, derechos y acciones que le fueron transferidos en el momento de su creación.`,
        `Todos aquellos bienes muebles e inmuebles, ingresos, derechos y acciones que adquiera de conformidad con la ley.`
      ]}
    ]},
    { t: "art", n: 25, ep: "Ingresos del Instituto Nacional de Transporte Terrestre", b: [
      { p: `Los ingresos del Instituto Nacional de Transporte Terrestre están constituidos por:` },
      { ol: [
        `Todos los ingresos que obtenga como resultado de su gestión, así como el producto resultante de sus actividades económicas con personas naturales o jurídicas, nacionales o extranjeras.`,
        `Los ingresos derivados de las multas impuestas y constancias de revisión, efectuadas por el Cuerpo Técnico de Vigilancia del Transporte Terrestre.`,
        `Los ingresos derivados de las multas impuestas por la gerencia de transporte terrestre.`,
        `Los recursos que le sean asignados en la Ley de Presupuesto Anual de cada ejercicio fiscal y los recursos extraordinarios que le acuerde el Ejecutivo Nacional.`,
        `Los derechos y acciones que adquiera por cualquier acto jurídico.`,
        `Las tasas y tarifas producto de sus servicios y habilitaciones.`,
        `Los demás recursos que lícitamente obtenga por cualquier concepto.`
      ]},
      { p: `En ningún caso, el Instituto podrá utilizar los ingresos provenientes de su gestión para fines distintos a su funcionamiento.` }
    ]},
    { t: "art", n: 26, ep: "Directorio del Instituto Nacional de Transporte Terrestre", b: [
      { p: `El Instituto Nacional de Transporte Terrestre tendrá un Directorio integrado por un Presidente o una Presidenta y un Vicepresidente o una Vicepresidenta, los cuales son de libre nombramiento y remoción del Presidente o Presidenta de la República, y tres Directores o Directoras, de libre nombramiento y remoción del ministro o ministra del poder popular con competencia en materia de transporte terrestre. Cada Director o Directora tendrá un suplente de libre nombramiento y remoción, y designado o designada de la misma forma, quien llenará sus faltas temporales.` }
    ]},
    { t: "art", n: 27, ep: "Requisitos y condiciones", b: [
      { p: `El Presidente o Presidenta del Instituto Nacional de Transporte Terrestre, los demás miembros del Directorio y sus suplentes, deben reunir las siguientes condiciones mínimas:` },
      { ol: [
        `Ser de nacionalidad venezolana.`,
        `Mayor de treinta (30) años de edad.`,
        `De reconocida solvencia ética y moral.`,
        `No estar sometido o sometida a interdicción civil ni a inhabilitación política.`,
        `Tener probada experiencia e idoneidad técnica y profesional en el sector transporte terrestre.`,
        `No tener participación accionaria en empresas del sector o empresas que tengan convenios o contratos, expectativas de tenerlos, con el Instituto Nacional de Transporte Terrestre, a menos que hayan transferido su titularidad accionaria con un mínimo de dos (2) años de anterioridad.`,
        `No haber sido declarado o declarada en estado de quiebra, culpable o fraudulenta, mediante sentencia firme, ni condenado o condenada por delitos contra la fe pública o contra el patrimonio público.`
      ]}
    ]},
    { t: "art", n: 28, ep: "Responsabilidad de los miembros del Directorio", b: [
      { p: `Los miembros del Directorio del Instituto Nacional de Transporte Terrestre serán solidariamente responsables, civil y administrativamente, de las decisiones adoptadas en las reuniones del Directorio, de acuerdo con las leyes que rigen la materia, a menos que hayan salvado sus votos o que no hubiesen asistido a la reunión de que se trate.` }
    ]},
    { t: "art", n: 29, ep: "Atribuciones del Directorio", b: [
      { p: `Son atribuciones del Directorio del Instituto Nacional de Transporte Terrestre, las siguientes:` },
      { ol: [
        `Aprobar internamente el plan operativo, el presupuesto anual del Instituto, los estados financieros y la memoria y cuenta del mismo.`,
        `Aprobar el reglamento interno del Instituto, propuesto por su Presidente o Presidenta y sus modificaciones cuando las circunstancias lo requieran.`,
        `Aprobar la creación, modificación o supresión de unidades técnicas y de las oficinas regionales que se consideren necesarias para el cumplimiento de los fines del Instituto.`,
        `Aprobar el estatuto de los funcionarios del Instituto.`,
        `Autorizar al Presidente o Presidenta del Instituto para suscribir y actualizar convenios y contratos que tengan por objeto el desarrollo y agilización de actividades y proyectos vinculados con el servicio del transporte terrestre, previa aprobación del ministro o ministra del poder popular con competencia en materia de transporte terrestre.`,
        `Autorizar la suscripción y extensión de la contratación colectiva con sus trabajadores o trabajadoras en los términos señalados por la ley.`,
        `Autorizar la adquisición y enajenación de bienes muebles e inmuebles propiedad del Instituto, de conformidad con lo dispuesto en la ley que rige la materia.`,
        `Autorizar al Presidente o a la Presidenta del Instituto o al Vicepresidente o Vicepresidenta, conjuntamente con el gerente de administración, para abrir, movilizar y cerrar las cuentas bancarias del Instituto, cumpliendo con las normas que rijan la materia.`,
        `Las demás que le confieran esta Ley y los reglamentos respectivos.`
      ]}
    ]},
    { t: "art", n: 30, ep: "Atribuciones del Presidente o Presidenta del Instituto", b: [
      { p: `Son atribuciones del Presidente o Presidenta del Instituto Nacional de Transporte Terrestre, las siguientes:` },
      { ol: [
        `Ejecutar, supervisar y controlar la aplicación de las políticas del sector transporte terrestre, emanadas del Ejecutivo Nacional.`,
        `Ejercer la representación y emitir los lineamientos necesarios para organizar, administrar, coordinar y controlar los recursos humanos, materiales y financieros del Instituto.`,
        `Ejecutar y hacer cumplir los actos de efectos generales o particulares que dicte el Directorio.`,
        `Nombrar, transferir, remover, destituir y ejercer la potestad disciplinaria del personal del Instituto, de conformidad con el correspondiente estatuto.`,
        `Celebrar en nombre del Instituto, previa aprobación del Directorio, convenios y contratos de obra, de adquisición de bienes o servicios, arrendamientos con organismos nacionales, públicos, privados e internacionales, así como con personas naturales y jurídicas.`,
        `Dictar los lineamientos generales para la elaboración del proyecto de presupuesto y someterlo a la consideración del Directorio, de conformidad con la ley.`,
        `Delegar atribuciones, la firma de determinados documentos o certificaciones, de conformidad con la normativa aplicable.`,
        `Presentar el proyecto de reglamento interno a la consideración del Directorio.`,
        `Convocar y presidir las sesiones del Directorio, así como suscribir los actos y documentos que emanen de sus decisiones.`,
        `Ejercer la representación judicial y extrajudicial del Instituto, pudiendo constituir apoderados generales o especiales.`,
        `Presentar la memoria y cuenta del Instituto a la consideración del ministro o ministra del poder popular con competencia en materia de transporte terrestre.`,
        `Suscribir las comunicaciones dirigidas a entidades bancarias, públicas o privadas, relacionadas con solicitudes de información sobre estados de cuenta por concepto de depósitos especiales para pagos de contratos y el movimiento de las cuentas, referentes a los fondos del Instituto.`,
        `Abrir, movilizar y cerrar las cuentas del Instituto, conjuntamente con el Vicepresidente o Vicepresidenta, o con el gerente de administración.`,
        `Las demás que le confieran la ley y los reglamentos.`
      ]}
    ]},
    { t: "art", n: 31, ep: "Atribuciones del Vicepresidente o Vicepresidenta del Instituto", b: [
      { p: `Son atribuciones del Vicepresidente o Vicepresidenta del Instituto Nacional de Transporte Terrestre, las siguientes:` },
      { ol: [
        `Cubrir las faltas temporales y las absolutas, hasta tanto se proceda a la nueva designación del Presidente o Presidenta del Instituto.`,
        `Representar en cualquier evento al Presidente o Presidenta del Instituto, por designación de éste.`,
        `Colaborar con el Presidente o Presidenta del Instituto en la ejecución, supervisión y control en la aplicación de las políticas del sector transporte terrestre, emanadas del Ejecutivo Nacional.`,
        `Colaborar con el Presidente o Presidenta del Instituto en la ejecución y cumplimiento de los actos de efectos generales o particulares emanados del Directorio.`,
        `Coordinar las políticas intersectoriales con los demás órganos del Poder Público.`,
        `Informar al Presidente o Presidenta del Instituto sobre el control del Sistema de Evaluación de Desempeño Gerencial.`,
        `Coordinar los proyectos de memoria y cuenta, informes anuales de gestión y boletín estadístico para la revisión del Presidente o Presidenta del Instituto.`,
        `Participar en la formulación y control de la estrategia comunicacional, con el propósito de contribuir a la proyección de la imagen adecuada del Instituto.`,
        `Las demás que le asigne el Presidente o Presidenta, y el Directorio.`
      ]}
    ]},
    { t: "cap", num: "III", nombre: "Del Fondo de Apoyo a la Seguridad Vial" },
    { t: "art", n: 32, ep: "De la creación del Fondo", b: [
      { p: `Se crea el Fondo de Apoyo a la Seguridad Vial, a los fines de administrar los recursos provenientes de las multas indicadas en el numeral 2 del artículo 25 de esta Ley; sin personalidad jurídica y dependiente del Instituto Nacional de Transporte Terrestre. El Fondo tendrá como objetivo principal optimizar la prestación del servicio de vigilancia y seguridad vial en el territorio nacional, mediante la elaboración de programas y proyectos de inversión en materia de equipamiento y educación vial; que serán sometidos anualmente o con la periodicidad que requieran las circunstancias, a la aprobación del Directorio del Instituto.` }
    ]},
    { t: "art", n: 33, ep: "Junta administradora del Fondo", b: [
      { p: `El Fondo de Apoyo a la Seguridad Vial estará administrado por una Junta Administradora integrada por tres (3) miembros de libre nombramiento y remoción, con sus respectivos suplentes, uno de los cuales será el coordinador o coordinadora de la Junta. El ministro o ministra del poder popular con competencia en materia de transporte terrestre designará al miembro coordinador y su suplente. Los otros miembros y sus suplentes serán designados o designadas, uno por el Presidente o Presidenta del Instituto Nacional de Transporte Terrestre y otro por el Director o Directora del Cuerpo Técnico de Vigilancia del Transporte Terrestre.` }
    ]},
    { t: "art", n: 34, ep: "Recursos del Fondo", b: [
      { p: `Los recursos del Fondo de Apoyo a la Seguridad Vial son aquellos que efectivamente hayan ingresado a las cuentas del mismo, de conformidad con el numeral 2 del artículo 25 de esta Ley. Igualmente, forman parte del Fondo de Apoyo a la Seguridad Vial los recursos que, conforme a otras leyes, se depositen en fideicomisos u otras modalidades para atender los programas de educación y seguridad vial.` }
    ]},
    { t: "art", n: 35, ep: "Del depósito de los recursos", b: [
      { p: `Los recursos del Fondo de Apoyo a la Seguridad Vial se depositarán en las cuentas bancarias destinadas a tal efecto, por el Instituto Nacional de Transporte Terrestre y podrán colocarse en inversiones que garanticen la mayor seguridad y liquidez de los mismos, de conformidad con la ley que rige la materia.` }
    ]},
    { t: "art", n: 36, ep: "De la distribución de los recursos por multas y revisiones", b: [
      { p: `Los recursos provenientes de las multas impuestas y constancias de revisión efectuadas por el Cuerpo Técnico de Vigilancia del Transporte Terrestre, serán distribuidos de la siguiente manera:` },
      { ol: [
        `Un cuarenta por ciento (40%) exclusivamente para fortalecimiento y equipamiento del Cuerpo Técnico de Vigilancia del Transporte Terrestre.`,
        `Un sesenta por ciento (60%) para el desarrollo e implantación de planes, programas y proyectos de educación y seguridad vial, y la escuela del transporte.`
      ]}
    ]},
    { t: "titulo", num: "III", nombre: "Registro del Sistema Nacional de Transporte Terrestre" },
    { t: "cap", num: "I", nombre: "Registro Nacional de Vehículos y de Conductores y Conductoras" },
    { t: "art", n: 37, ep: "De la autoridad competente", b: [
      { p: `Se llevará un Registro Nacional de Vehículos y de Conductores y Conductoras, el cual deberá garantizar la mayor transparencia en los trámites y procedimientos.` },
      { p: `La organización y funcionamiento del Registro Nacional de Vehículos y de Conductores y Conductoras serán determinados por el Instituto Nacional de Transporte Terrestre.` }
    ]},
    { t: "art", n: 38, ep: "Del carácter público del Registro", b: [
      { p: `El Registro Nacional de Vehículos y de Conductores y Conductoras, será público, sólo los actos inscritos en el mismo surtirán efectos frente a terceros, así como las certificaciones de éstos que emita el Instituto, las cuales serán otorgadas en la forma prevista en el Reglamento de esta Ley, por el Registrador o Registradora Nacional de Transporte Terrestre o por los Registradores Delegados o las Registradoras Delegadas.` },
      { p: `A los fines del presente artículo, el vendedor o la vendedora deberá notificar al Registrador Delegado o Registradora Delegada de la jurisdicción donde resida o haya vendido el vehículo, dentro de los treinta (30) días siguientes a la enajenación del vehículo, del acto notarial respectivo, con el cual se liberará de toda responsabilidad, civil y administrativa frente a terceros, por hechos posteriores a la venta no imputables al vendedor o vendedora.` },
      { p: `El incumplimiento de la presente obligación dentro del lapso establecido acarreará la multa respectiva, y la notificación efectuada con posterioridad surtirá plenos efectos a partir de la fecha de su realización.` }
    ]},
    { t: "art", n: 39, ep: "Presencia y certificación de los actos de traspasos y registros", b: [
      { p: `Los Registradores Delegados o Registradoras Delegadas pueden presenciar y certificar los actos de traspasos de vehículos o recibir del vendedor o vendedora, o comprador o compradora las manifestaciones de voluntad y las actuaciones notariales o judiciales que fueren pertinentes, así como las experticias relativas al número de identificación y características del vehículo, realizada por los funcionarios especializados del Cuerpo Técnico de Vigilancia del Transporte Terrestre, y tramitar, conforme a lo previsto en el Reglamento de esta Ley, la documentación respectiva. Igualmente, recibirán, vía postal, dichas actuaciones notariales o judiciales y expedirán por la misma vía o por cualquier otro medio idóneo los resultados de su tramitación.` },
      { p: `En ningún caso podrá exceder, la consignación, tramitación y entrega por parte de la Administración de los documentos respectivos atinentes a la solicitud de que se trate, sea definitiva o de mero trámite, de veinte (20) días hábiles a partir de la fecha de recibo de la solicitud y sus anexos por vía postal, y de cinco (5) días hábiles en los demás casos realizados en forma directa.` }
    ]},
    { t: "art", n: 40, ep: "Vehículos exceptuados del Registro Nacional", b: [
      { p: `Los vehículos propiedad de la República Bolivariana de Venezuela, deben estar inscritos en el Registro Nacional de Vehículos y de Conductores y Conductoras, exceptuando los artillados propiedad de la Fuerza Armada Nacional, cuyo registro lo llevará la autoridad militar correspondiente, la cual suministrará la información requerida por las autoridades competentes, en caso de accidentes de tránsito.` }
    ]},
    { t: "art", n: 41, ep: "Desincorporación de vehículos por programas de renovación", b: [
      { p: `Los vehículos usados, utilizados para el servicio de transporte terrestre público de personas y de carga, que hayan sido incluidos para su sustitución en los programas de renovación promovidos por el Estado, deben ser desincorporados del Registro Nacional de Vehículos y de Conductores y Conductoras. A tales efectos, los organismos encargados de estos programas deben efectuar la respectiva notificación al Instituto Nacional de Transporte Terrestre, en un lapso no mayor a treinta (30) días, contados a partir de la inclusión en los programas de renovación del respectivo vehículo.` }
    ]},
    { t: "art", n: 42, ep: "Certificaciones y reportes", b: [
      { p: `Los peritos avaluadores autorizados por el Instituto Nacional de Transporte Terrestre, están obligados a certificar y reportar mensualmente a éste, los vehículos que hayan sido calificados como inservibles, con la finalidad de desincorporarlos del Registro Nacional de Vehículos y de Conductores y Conductoras.` }
    ]},
    { t: "art", n: 43, ep: "Centros de componentes automotrices usados", b: [
      { p: `Los centros de compra y venta de componentes automotrices usados, están obligados a reportar mensualmente al Instituto Nacional de Transporte Terrestre, los vehículos o componentes de vehículos que adquieran, con la finalidad de ser desincorporados del Registro Nacional de Vehículos y de Conductores y Conductoras. De no cumplir con lo establecido en este artículo incurrirán en las sanciones establecidas en esta Ley.` }
    ]},
    { t: "art", n: 44, ep: "Organizaciones aseguradoras", b: [
      { p: `Las empresas u organizaciones aseguradoras de vehículos están obligadas a reportar mensualmente al Registro Nacional de Vehículos y de Conductores y Conductoras, aquellos vehículos que hayan sido calificados como pérdida total o no recuperable.` },
      { p: `Corresponde a los peritos avaluadores debidamente autorizados por el Instituto Nacional de Transporte Terrestre, expedir la calificación previa indicada en este artículo.` }
    ]},
    { t: "cap", num: "II", nombre: "De los Vehículos" },
    { t: "art", n: 45, ep: "De la clasificación de los vehículos", b: [
      { p: `A los fines de esta Ley, los vehículos de transporte terrestre se clasifican en:` },
      { ol: [
        `No motorizados o de tracción a sangre.`,
        `A motor.`,
        `Maquinarias y aparatos aptos para circular.`
      ]},
      { p: `La tipología y características técnicas de los vehículos se regirán por lo establecido en las Normas del Sistema Nacional de Calidad y por el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 46, ep: "Condiciones de seguridad de los vehículos", b: [
      { p: `Todo vehículo a motor debe mantenerse en perfectas condiciones de seguridad, funcionamiento, control de emisiones de gases contaminantes y ruido, según lo establecido en esta Ley, su Reglamento y en concordancia con el ordenamiento jurídico en la materia. A tal efecto, el propietario o la propietaria está obligado u obligada a efectuar la revisión técnica del vehículo en los términos expuestos en esta Ley y su Reglamento.` }
    ]},
    { t: "art", n: 47, ep: "Dispositivos de control y registro de velocidad", b: [
      { p: `Todo vehículo automotor deberá tener instalado y en perfecto estado de funcionamiento, dispositivos que permitan obtener un registro gráfico de la velocidad y distancia recorrida, en función del tiempo y características de la vía, de conformidad con el Reglamento de esta Ley. Los dispositivos de control a que se refiere este artículo deberán demostrar anualmente la idoneidad de sus sistemas.` }
    ]},
    { t: "art", n: 48, ep: "Mecanismos de control de velocidad", b: [
      { p: `Las autoridades administrativas competentes, en el ámbito de sus respectivas jurisdicciones, implementarán los mecanismos que permitan realizar el correspondiente control de velocidad de los vehículos automotores.` }
    ]},
    { t: "art", n: 49, ep: "Autorización y asignación de placas identificadoras de vehículos a comercializar", b: [
      { p: `El Instituto Nacional de Transporte Terrestre autorizará y asignará a los fabricantes, ensambladoras, carroceras e importadoras de vehículos las placas identificadoras de los vehículos a comercializar, cualquiera sea su tipología, previo el cumplimiento de los siguientes requisitos:` },
      { ol: [
        `Estar legalmente constituidos en el país.`,
        `Estar inscritos en el registro de empresas fabricantes, ensambladoras, distribuidoras e importadoras llevados por el Instituto Nacional de Transporte Terrestre y el ministerio del poder popular con competencia en materia de industrias ligeras y comercio.`,
        `Identificar los vehículos a comercializar mediante la marca, modelo, tipo, capacidad, peso, tara, número de identificación de vehículo (VIN), serial de motor, serial de carrocería, tipología y características técnicas, de conformidad con las disposiciones reglamentarias y las Normas del Sistema Nacional de Calidad.`,
        `En caso de vehículos importados deberá consignarse la documentación de nacionalización emitida por la autoridad competente.`,
        `Los demás requisitos y procedimientos que determine el Reglamento de esta Ley.`
      ]}
    ]},
    { t: "art", n: 50, ep: "Certificado de homologación de vehículos", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es el ente autorizado para otorgar el certificado de homologación de vehículos, cuyos requisitos y elementos se establecerán en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 51, ep: "Certificado de homologación previa comercialización", b: [
      { p: `Los fabricantes, ensambladoras, carroceras e importadoras de vehículos deben solicitar ante el Instituto Nacional de Transporte Terrestre, previa a su comercialización, el certificado de homologación, consignando la documentación técnica necesaria de los modelos a comercializar.` },
      { p: `Para la prestación del servicio de transporte terrestre público y privado de personas y de carga, las unidades no podrán ser objeto de financiamiento por entes públicos o privados, si no cumplen con las Normas del Sistema Nacional de Calidad.` }
    ]},
    { t: "art", n: 52, ep: "Revisión técnica, mecánica y física de vehículos", b: [
      { p: `El Instituto Nacional de Transporte Terrestre, practicará la revisión técnica, mecánica y física de los vehículos, a los fines de verificar el buen estado de funcionamiento y las características de las unidades del parque automotor existente. Los resultados de la revisión serán insertados al Registro Nacional de Vehículos y de Conductores y Conductoras. Los vehículos que no aprueben la revisión no podrán circular por las vías públicas o privadas destinadas al uso público.` }
    ]},
    { t: "art", n: 53, ep: "De las estaciones para la revisión técnica", b: [
      { p: `El Instituto Nacional de Transporte Terrestre establecerá los requisitos y normas para la instalación y funcionamiento de las estaciones para la revisión técnica, mecánica y física de vehículos.` }
    ]},
    { t: "art", n: 54, ep: "De los procedimientos de la revisión", b: [
      { p: `El Instituto Nacional de Transporte Terrestre, establecerá los procedimientos específicos de la revisión técnica, mecánica y física de vehículos, así como las medidas aplicables en los casos de vehículos que no aprueben la revisión, pudiendo ordenar su desincorporación del Registro Nacional de Vehículos y de Conductores y Conductoras, en aquellos casos en los cuales, debido al deterioro del vehículo, se determine que es inservible de manera permanente.` }
    ]},
    { t: "art", n: 55, ep: "Verificación legal de vehículos usados", b: [
      { p: `Toda persona, a fin de verificar las condiciones legales de cualquier unidad, puede consultar el Registro Nacional de Vehículos y de Conductores y Conductoras; si existiere interés legítimo, podrá solicitar la realización de la experticia de verificación de seriales y características por ante los funcionarios especializados o funcionarias especializadas del Cuerpo Técnico de Vigilancia del Transporte Terrestre. A estos fines, tanto el Instituto, como el Cuerpo Técnico de Vigilancia del Transporte Terrestre, mantendrán los sistemas de información y de verificación correspondientes. La forma de acceder a tales sistemas se establecerá en el Reglamento de esta Ley.` },
      { p: `En materia de experticias y verificación de seriales, tienen competencia concurrente los funcionarios especializados o funcionarias especializadas en robo y hurto de vehículos del Cuerpo de Investigaciones Penales, Científicas y Criminalísticas.` }
    ]},
    { t: "art", n: 56, ep: "Obligación de desincorporación de vehículos del Registro", b: [
      { p: `El propietario o la propietaria de un vehículo a motor declarado como inservible de manera permanente, está obligado u obligada a desincorporarlo del Registro respectivo antes de venderlo en su totalidad; o como partes o piezas para componentes de vehículos usados.` },
      { p: `El Reglamento de esta Ley establecerá los requisitos y formas para la desincorporación de vehículos.` }
    ]},
    { t: "art", n: 57, ep: "De las modificaciones", b: [
      { p: `Cualquier transformación, modificación o cambio en sus características técnicas originales que altere la estructura, función o aspecto de un vehículo, y que éste en ningún caso afecte la seguridad del transporte terrestre, podrá efectuarse solamente previa autorización, expendida por el Instituto Nacional de Transporte Terrestre.` }
    ]},
    { t: "art", n: 58, ep: "De las pólizas de seguros", b: [
      { p: `Todo vehículo a motor debe estar amparado por una póliza de seguro de responsabilidad civil, para responder suficientemente por los daños que ocasione al Estado o a los y las particulares. Igualmente resultará obligatorio el seguro de responsabilidad civil para las motocicletas, en las mismas condiciones que rige para los automotores.` },
      { p: `En el caso de vehículos destinados al servicio de transporte terrestre público y privado de personas, sus propietarios o propietarias deben contratar adicionalmente una póliza de seguro de accidentes personales que cubra a las personas que transporta y su equipaje.` }
    ]},
    { t: "art", n: 59, ep: "Placas identificadoras", b: [
      { p: `Todo vehículo que circule por el territorio nacional, debe portar, de manera visible, sus correspondientes placas identificadoras, colocadas en la parte delantera y la otra en la parte posterior, en los sitios especialmente destinados a tal fin.` },
      { p: `El Instituto Nacional de Transporte Terrestre es el organismo competente para autorizar la fabricación, expedición y asignación de las placas identificadoras; así como para determinar su formato, características y clasificación.` }
    ]},
    { t: "art", n: 60, ep: "Reposición de las placas identificadoras", b: [
      { p: `En caso de destrucción o deterioro, robo, hurto o extravío de las placas identificadoras, el interesado solicitará al Instituto Nacional de Transporte Terrestre la reposición de las placas correspondientes, cumpliendo con los requisitos establecidos por el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 61, ep: "Vehículos con placas extranjeras", b: [
      { p: `Los vehículos que en el marco de los acuerdos o convenios internacionales suscritos por la República Bolivariana de Venezuela ingresen al país en condición de turistas, podrán circular con sus placas identificadoras de origen durante el tiempo de su estadía legal, siempre que posean la garantía o póliza de responsabilidad civil y se sometan a todos los requisitos que fije el Instituto Nacional de Transporte Terrestre.` }
    ]},
    { t: "art", n: 62, ep: "Permiso provisional", b: [
      { p: `El Instituto Nacional de Transporte Terrestre otorgará un permiso provisional para la circulación de los vehículos que no porten placas identificadoras, por un lapso de treinta (30) días prorrogables.` }
    ]},
    { t: "cap", num: "III", nombre: "De las Licencias" },
    { t: "art", n: 63, ep: "Licencia de conducir", b: [
      { p: `Para conducir un vehículo, la persona debe obtener y portar la licencia o título profesional de conducir, vigente, del grado o categoría que corresponda al tipo de vehículo a motor respectivo, expedida por el Instituto Nacional de Transporte Terrestre y el Certificado Médico de Salud Integral vigente, además el conductor o conductora de vehículos destinados a la prestación del servicio de transporte terrestre público y privado de pasajeros y pasajeras, deberá obtener y portar el certificado de conducir expedido por la Escuela del Transporte avalado por el Instituto Nacional del Transporte Terrestre.` },
      { p: `La licencia de conducir de un grado superior, permitirá a su titular la conducción de vehículos para los cuales se requiere un grado inferior, con excepción de la conducción de motocicletas.` },
      { p: `La licencia de conducir sólo podrá ser expedida, renovada, suspendida, anulada o revocada por el Instituto Nacional de Transporte Terrestre. Los órganos jurisdiccionales competentes, podrán ordenar la revocatoria.` },
      { p: `El ministerio del poder popular con competencia en materia de salud expedirá gratuitamente el Certificado Médico de Salud Integral, en el que se incluye todos los parámetros necesarios para conducir, en los términos establecidos por el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 64, ep: "Del Registro de licencias", b: [
      { p: `El Instituto Nacional de Transporte Terrestre, a través de los Registradores Delegados o Registradoras Delegadas recibirán y tramitarán las solicitudes de los usuarios y las usuarias de sus respectivas circunscripciones, para la obtención de las licencias o títulos de conducir.` }
    ]},
    { t: "art", n: 65, ep: "Requisitos adicionales", b: [
      { p: `En el Reglamento de esta Ley se establecerán los requisitos y condiciones, así como la obligación de realizar y aprobar cursos y exámenes especiales para obtener la licencia de conducir vehículos destinados al transporte de carga, transporte terrestre público de pasajeros y pasajeras, transporte escolar, turístico, de ambulancias, de bomberos, de valores, policiales o similares y para obtener el certificado de conducir vehículo destinado al servicio de transporte terrestre público de pasajeros y pasajeras.` }
    ]},
    { t: "art", n: 66, ep: "Licencia para extranjeros y extranjeras", b: [
      { p: `En el Reglamento de esta Ley se determinará todo lo relacionado con el otorgamiento de licencias para extranjeros y extranjeras.` }
    ]},
    { t: "art", n: 67, ep: "Clasificación de las licencias para conducir", b: [
      { p: `Las licencias para conducir se otorgarán por grado, de acuerdo con los tipos de vehículos y la capacidad que exija su conducción. El grado indica la capacidad del sujeto para conducir vehículos de determinado tipo. Las licencias serán de cinco (5) grados:` },
      { ol: [
        `Licencias de primer grado (1°) para conducir vehículos no motorizados. Tipo "A", a personas mayores de catorce (14) años de edad, para conducir vehículos de tracción humana; Tipo "B", a personas mayores de dieciséis (16) años de edad, para conducir vehículos de tracción animal.`,
        `Licencias de segundo grado (2°) para conducir motocicletas. Tipo "A", a personas mayores de dieciséis (16) años de edad para conducir motocicletas con cilindrada hasta ochenta centímetros cúbicos (80 cm3); Tipo "B", a personas mayores de dieciocho (18) años de edad para conducir motocicletas de cualquier cilindrada.`,
        `Licencias de tercer grado (3°) para conducir vehículos a motor destinados al transporte privado de personas, con capacidad hasta de nueve (9) puestos, incluyendo el del conductor o conductora; vehículos destinados al transporte de mercancías, cuya capacidad de carga y peso bruto vehicular máximo no exceda los dos mil quinientos kilogramos (2.500 Kgs). Tipo "A", a las personas mayores de dieciséis (16) años de edad y menores de dieciocho (18) años de edad, sujetas al régimen especial restrictivo previsto en el Reglamento de esta Ley; Tipo "B", a las personas mayores de dieciocho (18) años de edad.`,
        `Licencias de cuarto grado (4°) a las personas mayores de veintiún (21) años de edad para conducir vehículos con capacidad hasta de doce (12) puestos destinados al transporte terrestre público de personas y los vehículos de carga, cuyo peso bruto vehicular no exceda los seis mil kilogramos (6.000 Kgs).`,
        `Licencias de quinto grado (5°) a personas mayores de veinticinco (25) años de edad, para conducir todo tipo de vehículos de transporte terrestre privado de personas, transporte terrestre público de personas en rutas urbanas, suburbanas e interurbanas, y transporte de carga hasta nueve mil kilogramos (9.000 Kgs), con la excepción de los vehículos indicados en el numeral 2 de este artículo.`,
        `Títulos profesionales a personas mayores de treinta (30) años de edad, sujetas al régimen especial previsto en el Reglamento de esta Ley para conducir todo tipo de vehículos con fines de lucro, cualquiera sea su capacidad o uso, con la excepción de los vehículos indicados en el numeral 2 de este artículo y los especificados en el artículo siguiente. Para el transporte de carga de alto riesgo se requerirá, además del título profesional, el certificado de aprobación del curso de conducción de vehículos de carga de alto riesgo.`
      ]}
    ]},
    { t: "art", n: 68, ep: "Licencias especiales", b: [
      { p: `Las personas con discapacidad que llenen los requisitos ordinarios para obtener licencia para conducir vehículos automotores, la tendrán en las mismas condiciones y con la duración ordinaria general para el grado en que fuera otorgada. Los certificados médicos de salud integral especiales que prueben la aptitud para manejar, deberán determinar el tipo y grado de discapacidad presentada.` }
    ]},
    { t: "art", n: 69, ep: "Licencias para funcionarios y funcionarias diplomáticos y consulares", b: [
      { p: `Los funcionarios y funcionarias diplomáticos o consulares acreditados en el país, podrán obtener la licencia para conducir, siempre y cuando exista reciprocidad de acuerdo a lo establecido en los convenios internacionales vigentes. Las condiciones y requisitos se establecerán en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 70, ep: "Suspensión, anulación y revocación de los permisos de conducir", b: [
      { p: `Las licencias y los títulos de conducir podrán ser suspendidos, anulados o revocados por la autoridad administrativa competente, que la haya expedido o el ente jurisdiccional competente por las causas previstas en esta Ley. Serán anuladas cuando hayan sido otorgadas mediante un acto viciado en razón de defectos de forma esenciales a su validez, o por falta de los requisitos de fondo. Serán revocadas cuando sobrevenga impedimento que incapacite física, mental o legalmente a su titular para conducir vehículos, y cualquiera otra prevista en el capítulo correspondiente a las sanciones administrativas, y serán suspendidas en los casos previstos en esta Ley.` }
    ]},
    { t: "cap", num: "IV", nombre: "De los Propietarios, Propietarias, Conductores, Conductoras y sus Obligaciones" },
    { t: "art", n: 71, ep: "De los propietarios y propietarias", b: [
      { p: `Se considera propietario o propietaria quien figure en el Registro Nacional de Vehículos y de Conductores y Conductoras como adquirente, aun cuando lo haya adquirido con reserva de dominio.` }
    ]},
    { t: "art", n: 72, ep: "Obligaciones de los propietarios y las propietarias de vehículos", b: [
      { p: `Todo propietario o propietaria de vehículo está sujeto a las siguientes obligaciones:` },
      { ol: [
        `Inscribir el vehículo en el Registro Nacional de Vehículos y de Conductores y Conductoras, dentro de los treinta (30) días hábiles siguientes a su adquisición, y efectuar las inscripciones que exija el Instituto Nacional de Transporte Terrestre dentro del mismo lapso.`,
        `Pagar oportunamente las tarifas, las tasas y demás contribuciones que lo graven.`,
        `Notificar al Registro Nacional de Vehículos y de Conductores y Conductoras las modificaciones de las características del vehículo de su propiedad y los cambios de identificación, domicilio o denominación comercial, en los términos que establezca el Reglamento de esta Ley.`,
        `Notificar por escrito, a través de los peritos avaluadores, autorizados por el Instituto Nacional de Transporte Terrestre, al Registro Nacional de Vehículos y de Conductores y Conductoras, cuando el vehículo se haga inservible de manera permanente o sea declarado pérdida total y demás casos previstos en esta Ley.`,
        `Mantener el vehículo en buenas condiciones de seguridad, funcionamiento, control de emisión de gases contaminantes del ambiente y ruidos.`,
        `Proveer al vehículo de toda la documentación y elementos de identificación establecidos por esta Ley, así como de sus correspondientes placas de identificación; renovándolas y manteniéndolas en perfecto estado de conservación y condiciones de visibilidad.`,
        `Efectuar la revisión, técnica, mecánica y física del vehículo en los términos que señale el Reglamento de esta Ley.`,
        `Mantener en vigencia el seguro de responsabilidad civil.`,
        `Las demás que señalen esta Ley y su Reglamento.`
      ]}
    ]},
    { t: "art", n: 73, ep: "Obligación del conductor o conductora", b: [
      { p: `Todo conductor o conductora de un vehículo a motor está sujeto a las siguientes obligaciones:` },
      { ol: [
        `Portar la licencia de conducir vigente del grado correspondiente al vehículo que conduce.`,
        `Portar el Certificado Médico de Salud Integral vigente.`,
        `Portar el certificado psicológico vigente en los casos previstos en el Reglamento de esta Ley.`,
        `Conducir en óptimo estado de salud, física y mental.`,
        `Usar el cinturón de seguridad y asegurarse que los demás ocupantes del vehículo cumplan esta obligación.`,
        `No provocar ruidos contaminantes al ambiente.`,
        `Asegurar que los niños o niñas menores de diez (10) años de edad, ocupen los asientos traseros del vehículo. Cuando se trate de infantes deben ser transportados, en todo caso, en asientos especiales para tal fin.`,
        `Cumplir y hacer cumplir las normas que en materia de seguridad del transporte terrestre establezca esta Ley, su reglamento y el ordenamiento jurídico.`
      ]}
    ]},
    { t: "titulo", num: "IV", nombre: "Del Transporte Terrestre" },
    { t: "cap", num: "I", nombre: "De la Circulación" },
    { t: "art", n: 74, ep: "Libre tránsito", b: [
      { p: `Las autoridades administrativas competentes, en el ámbito de sus respectivas jurisdicciones, garantizarán que la circulación peatonal y vehicular por las vías públicas, se realice de manera fluida, conveniente, segura y sin impedimentos de ninguna especie.` },
      { p: `Por ningún motivo podrá impedirse el libre tránsito de vehículos o peatones en una vía pública. Los ciudadanos y las ciudadanas, previa obtención de la autorización emanada de la autoridad competente, tienen derecho a manifestar, sin afectar, obstruir o impedir el libre tránsito de personas y vehículos.` },
      { p: `La regulación para la circulación de los peatones, el tránsito de vehículos motorizados o no, los límites máximos y mínimos de velocidad, se establecerán en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 75, ep: "Dispositivos para el control del tránsito", b: [
      { p: `El Reglamento de esta Ley establecerá las normas y manuales nacionales e internacionales aplicables en materia de dispositivos para el control del tránsito, a ser utilizados en las vías públicas y privadas en todo el territorio nacional.` }
    ]},
    { t: "art", n: 76, ep: "Conservación, mantenimiento de la señalización y demarcación", b: [
      { p: `Las autoridades administrativas competentes, en el ámbito de sus respectivas jurisdicciones, son responsables de conservar, preservar y mantener la señalización y demarcación de las vías y dispositivos del tránsito, incluyendo las contentivas de la materia de educación y seguridad vial y las de carácter preventivo que sean necesarias en las vías públicas y privadas.` },
      { p: `Está terminantemente prohibido alterar, destruir, deteriorar o remover las señales y otros dispositivos de control de tránsito. Los ciudadanos y las ciudadanas tienen el deber de coadyuvar con las autoridades administrativas en la conservación de las señales y dispositivos de tránsito.` }
    ]},
    { t: "art", n: 77, ep: "Horarios para el transporte de carga", b: [
      { p: `El Instituto Nacional de Transporte Terrestre establecerá los horarios para la circulación de vehículos destinados al transporte de carga en las vías de competencia nacional.` },
      { p: `La autoridad administrativa competente, establecerá los horarios para carga, descarga, así como el de recolección de los desperdicios y escombros, haciéndolos coincidir con períodos de menor congestión vehicular, en concordancia con lo previsto en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 78, ep: "Regulación de la utilización de obstáculos en las vías", b: [
      { p: `La utilización de obstáculos que impidan el libre tránsito o representen riesgos a la seguridad de los usuarios y de las usuarias, en vías públicas o privadas destinadas al uso público en el territorio nacional, se regulará de acuerdo a lo dispuesto en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 79, ep: "Remoción de obstáculos", b: [
      { p: `Las autoridades administrativas o los órganos de ejecución en el ámbito de su jurisdicción, quedan facultadas para remover los obstáculos, obras, vehículos u objetos que se encuentren ubicados, estacionados, que se presuman abandonados o se encuentren depositados en la vía pública, en zonas prohibidas o en sitios que obstaculicen el normal desarrollo de la circulación vehicular y peatonal. En el Reglamento de esta Ley se establecerá el procedimiento a seguir en estos casos.` }
    ]},
    { t: "art", n: 80, ep: "Responsabilidad por remoción de vehículos", b: [
      { p: `La facultad de remover vehículos mal estacionados no releva a la Administración de responsabilidad por los daños ocasionados a los mismos, debido a la acción culposa en la operación efectuada. En todo caso, son solidariamente responsables la Administración, los propietarios o las propietarias de las unidades de remolque y sus garantes, frente a los afectados por los daños ocasionados.` }
    ]},
    { t: "art", n: 81, ep: "Competencias deportivas", b: [
      { p: `Las competencias deportivas en las carreteras y autopistas nacionales públicas, se regulará de acuerdo con lo dispuesto en el Reglamento de esta Ley. Las realizadas en circuito cerrado se regirán por la ley que rige la materia.` }
    ]},
    { t: "art", n: 82, ep: "Permisos para la ejecución de trabajos en red vial nacional", b: [
      { p: `Las personas, organismos públicos o privados que requieran efectuar trabajos que afecten la circulación, deberán obtener la autorización respectiva de la autoridad administrativa competente; participarlo con la debida antelación e indicar su naturaleza, fecha de inicio, duración estimada y la restricción que causará a la circulación, de acuerdo a lo establecido en el Reglamento de esta Ley.` },
      { p: `La autoridad administrativa competente, dispondrá de un plazo de setenta y dos (72) horas para dar respuesta a la solicitud y podrá indicar que los trabajos de que se trate se realicen en otra fecha u hora e indicará las señales y demás medidas de prevención que juzgue necesarias.` }
    ]},
    { t: "art", n: 83, ep: "De la paralización de los trabajos en la red vial nacional", b: [
      { p: `La ejecución de trabajos a que se refiere el artículo anterior sin el cumplimiento de los requisitos y autorizaciones, dará lugar a la paralización de los mismos y a la restitución del estado físico del lugar a sus condiciones originales, anteriores a la iniciación de los trabajos. Los costos correrán a cargo de quien haya ejecutado la obra. Serán nulas de manera absoluta las autorizaciones emitidas estadal o localmente para la ejecución de dichos trabajos, a menos que las obras, como forma de aprovechamiento de la vialidad y del derecho de vía nacionales, hayan sido sometidas a la coordinación respectiva entre la gobernación de que se trate y el Ejecutivo Nacional, en cuyo caso se entenderán en conocimiento los organismos del Poder Público Nacional competentes para el control del transporte terrestre.` }
    ]},
    { t: "art", n: 84, ep: "Condiciones de circulación de los peatones y vehículos no motorizados", b: [
      { p: `Las autoridades administrativas competentes implementarán, los sistemas de tránsito peatonal y de vehículos, tipo bicicleta o cualquier otro de tracción a sangre, a fin de garantizar su circulación y prioridades de paso por las vías públicas y demás zonas especialmente acondicionadas para ello.` },
      { p: `El Reglamento de esta Ley, establecerá las normas especiales para la circulación de peatones y bicicletas o cualquier otro de tracción a sangre.` },
      { p: `En las aceras o aquellas zonas especialmente destinadas para la circulación peatonal, no podrán colocarse ningún tipo de obstáculo que impida el normal desarrollo de la circulación de peatones.` }
    ]},
    { t: "art", n: 85, ep: "Restricciones para la ocupación de los asientos delanteros de los vehículos", b: [
      { p: `En todos los vehículos de carga con capacidad mayor a los tres mil quinientos kilogramos (3.500 Kgs), no se permite el transporte de personas menores de diez (10) años; con las excepciones previstas en el Reglamento de esta Ley. En los vehículos de transporte terrestre público de personas, no se permite viajar en los asientos delanteros a menores de diez (10) años, personas con discapacidad y mujeres en estado de gravidez; a tal fin, los vehículos deberán contar con espacios y asientos especialmente acondicionados.` }
    ]},
    { t: "art", n: 86, ep: "Obligaciones en casos de accidentes", b: [
      { p: `Todo conductor o conductora implicado o implicada en un accidente de tránsito deberá:` },
      { ol: [
        `Detener el vehículo, en el lugar del accidente.`,
        `Cerciorarse si se han producido víctimas personales o daños a bienes públicos o privados como consecuencia del accidente y prestarle a las personas los debidos auxilios, procurando mantener el estado de las cosas.`,
        `Avisar a la autoridad competente en todo caso.`,
        `Salvaguardar la fluidez y seguridad de la circulación e intercambiarse recíprocamente los datos de identificación de los vehículos y de las personas involucradas en el accidente y de ser posible de los testigos presenciales.`
      ]},
      { p: `Lo dispuesto en los numerales 2 y 3 de este artículo se aplicará también a los testigos presenciales y otras personas que se hagan presentes en el sitio del accidente.` }
    ]},
    { t: "art", n: 87, ep: "Tiempo de conducción y descanso", b: [
      { p: `Las personas naturales y jurídicas autorizadas para la prestación del servicio de transporte terrestre público de pasajeros y pasajeras, y de carga están obligadas a cumplir con los tiempos de conducción y descanso que a tal efecto se establecerán en el Reglamento de esta Ley. Igualmente, deben cumplir con la obligación de llevar el personal debidamente habilitado para el relevo en la conducción de tales vehículos.` }
    ]},
    { t: "cap", num: "II", nombre: "De la Seguridad y Educación Vial" },
    { t: "art", n: 88, ep: "Obligatoriedad de la educación y seguridad vial", b: [
      { p: `El ministerio del poder popular con competencia en materia de educación, incluirá en todos los niveles y modalidades del sistema educativo venezolano, programas permanentes de enseñanza en materia del sistema de transporte terrestre, educación y seguridad vial.` },
      { p: `Las personas jurídicas, públicas, privadas y la sociedad civil organizada, actuarán coordinadamente con los organismos competentes en materia de transporte terrestre y de protección civil, en el desarrollo de los programas de enseñanza que se imparten de manera permanente, así como los de formación cívica y prevención.` }
    ]},
    { t: "art", n: 89, ep: "Participación ciudadana", b: [
      { p: `Las autoridades administrativas competentes fomentarán la participación de la ciudadanía en la difusión y observancia de las reglas y normas del transporte terrestre. Para ello podrán organizarse brigadas de voluntarios, coordinadas por tales autoridades que apoyen la realización de la participación ciudadana en las materias y casos que establezcan el Reglamento de esta Ley.` },
      { p: `Los recursos destinados al fortalecimiento de programas de educación vial deberán atender a las organizaciones de voluntarios de transporte terrestre, dándole prioridad a aquellas que tengan su origen en los Consejos Comunales.` }
    ]},
    { t: "art", n: 90, ep: "Publicidad institucional y comercial", b: [
      { p: `La colocación de toda publicidad institucional y comercial, tales como vallas, señales, carteles, dibujos, avisos luminosos, pancartas y demás medios similares conocidos o por conocerse, deberá ser permisada por la autoridad competente.` },
      { p: `Es competencia del Instituto Nacional de Transporte Terrestre autorizar la instalación de publicidad institucional y comercial en las adyacencias del derecho de vía de las carreteras y autopistas nacionales, previa verificación del cumplimiento de los requisitos establecidos en esta Ley y su Reglamento.` },
      { p: `Es competencia de los municipios autorizar la instalación de publicidad institucional y comercial en las inmediaciones de las vías urbanas, así como la fase interurbana de las carreteras y autopistas nacionales, previa verificación del cumplimiento de los requisitos técnicos establecidos por dichos entes u órganos políticos territoriales en las ordenanzas municipales que a tal fin se dicten.` },
      { p: `A los efectos del párrafo anterior se entenderá por fase interurbana de carreteras y autopistas nacionales, aquellos tramos que atraviesen áreas o centros poblados dentro de la zona geográfica de un municipio.` },
      { p: `Corresponde exclusivamente a los municipios la competencia para supervisar y controlar que la colocación de vallas y demás modalidades de colocación de publicidad institucional y comercial se ajuste a las Ordenanzas Municipales referentes a la materia de publicidad exterior, así como también le corresponde la sustanciación y decisión de los procedimientos administrativos indicados con ocasión al presunto incumplimiento de dicha normativa y la aplicación de las sanciones administrativas a que haya lugar.` }
    ]},
    { t: "art", n: 91, ep: "Prohibición de instalación de medios publicitarios", b: [
      { p: `Queda prohibida la instalación de medios publicitarios en las intersecciones de vías, distribuidores de tránsito, puentes, viaductos, túneles, pasos peatonales y separadores de avenidas, autopistas y carreteras.` }
    ]},
    { t: "art", n: 92, ep: "Prohibición de colocación de cierto tipo de publicidad", b: [
      { p: `Queda prohibida la colocación de anuncios, carteles, vallas y avisos publicitarios, comerciales o institucionales en toda la red vial, pública o privada de uso público, permanente o casual y en una franja de los predios colindantes a las mismas equivalente a cincuenta metros (50 mts) medidos desde el eje de la vía en las autopistas nacionales; de treinta metros (30 mts) medidos desde el eje de la vía en las carreteras pavimentadas y quince metros (15 mts) medidos desde el eje de la vía en las carreteras no pavimentadas, dentro o fuera del derecho de vía.` },
      { p: `Igualmente queda prohibida la colocación de éstos medios publicitarios tanto en la vía pública como en las unidades de transporte terrestre público y privado de personas y de carga que contengan mensajes de:` },
      { ol: [
        `Cigarrillos y derivados del tabaco.`,
        `Bebidas alcohólicas y demás especies previstas en la legislación sobre la materia.`,
        `Sustancias estupefacientes o psicotrópicas prohibidas por la ley que rige la materia.`,
        `Servicios profesionales prestados por personas que no posean o cumplan con los requisitos o condiciones exigidos por la ley.`,
        `Bienes, servicios o actividades cuya difusión haya sido prohibida o restringida, en forma temporal o permanente, por motivos de salud pública o garantía de los derechos de las personas, por la ley o las autoridades competentes, o no haya sido autorizada, según sea el caso.`,
        `Juegos de envite y azar que denigren del trabajo como hecho social y proceso fundamental para alcanzar los fines del Estado, o en los cuales participen niños, niñas o adolescentes, salvo que se trate de rifas benéficas por motivo de ayuda humanitaria.`,
        `Bienes o servicios dirigidos a niños, niñas o adolescentes que muestren o utilicen elementos de violencia regulados en esta Ley.`,
        `Armas, explosivos bienes o servicios relacionados y similares.`
      ]}
    ]},
    { t: "art", n: 93, ep: "Señales de tránsito", b: [
      { p: `Se prohíbe colocar o mantener en las vías públicas, signos, demarcaciones, publicidad o elementos que imiten o se asemejen a las señales del tránsito, o colocar en ellas anuncios de cualquier índole.` }
    ]},
    { t: "titulo", num: "V", nombre: "De los Servicios de Transporte" },
    { t: "cap", num: "I", nombre: "Competencias en Materias de Servicios de Transporte" },
    { t: "art", n: 94, ep: "Competencias de la autoridad nacional", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es el ente competente para autorizar, regular, supervisar y controlar el servicio de transporte terrestre público de pasajeros y pasajeras, en rutas urbanas intermunicipales que no estén sujetas a autoridades metropolitanas o mancomunidades, en materia de transporte terrestre público de pasajeros y pasajeras y en todos los casos de rutas suburbanas e interurbanas, no municipales o estadales.` }
    ]},
    { t: "art", n: 95, ep: "Autoridades metropolitanas y mancomunidades", b: [
      { p: `Las autoridades de los distritos metropolitanos, mancomunidades u otras formas asociativas intergubernamentales, son los órganos competentes para autorizar, regular, supervisar y controlar el servicio de transporte terrestre público de pasajeros y pasajeras en rutas urbanas intermunicipales, así como la clasificación de sus rutas de acuerdo con lo establecido en esta Ley y su Reglamento, dentro de sus respectivas jurisdicciones.` }
    ]},
    { t: "art", n: 96, ep: "Competencias de los municipios", b: [
      { p: `Las autoridades de los municipios son competentes para autorizar, regular, supervisar y controlar el transporte terrestre público de pasajeros y pasajeras urbano, suburbano e interurbano dentro de sus respectivas jurisdicciones, aun cuando los municipios se encuentren integrados a distritos metropolitanos, salvo que las rutas suburbanas sean declaradas por la autoridad competente con carácter metropolitano o que la ley de la materia disponga situación diferente.` }
    ]},
    { t: "art", n: 97, ep: "Competencia en el transporte de carga", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es la autoridad competente en todo el territorio nacional para autorizar, sistematizar y supervisar el servicio de transporte terrestre de carga. Será competencia de los estados, en coordinación con el Instituto Nacional de Transporte Terrestre a través del Cuerpo Técnico de Vigilancia del Transporte Terrestre, el control de este servicio en la red vial nacional. La circulación, estacionamiento y demarcación, así como la naturaleza, peso, volumen, peligrosidad y otras características particulares de la carga, serán regulados en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 98, ep: "Control de carga", b: [
      { p: `Los estados en el ámbito de su jurisdicción deben prever en tramos de autopistas o carreteras administradas directamente o bajo el régimen de concesiones viales, la instalación de balanzas o equipos de control de carga requeridos por la autoridad competente, de acuerdo al Plan de Control de Carga que al efecto realice el ministerio del poder popular con competencia en materia de transporte terrestre, cuya ejecución y supervisión estará a cargo del Instituto Nacional de Transporte Terrestre.` }
    ]},
    { t: "cap", num: "II", nombre: "De la Clasificación del Servicio" },
    { t: "art", n: 99, ep: "Clasificación del servicio de transporte terrestre", b: [
      { p: `Para los efectos de esta Ley, el servicio de transporte terrestre se clasifica en:` },
      { lv: [
        [0, `Transporte terrestre de personas:`],
        [1, `a) Público`],
        [2, `a.1 Colectivo`],
        [2, `a.2 Individual`],
        [1, `b) Privado`],
        [0, `Transporte terrestre de carga:`],
        [1, `a) General, a granel, perecedera y frágil`],
        [1, `b) De alto riesgo.`],
        [0, `Servicios conexos.`]
      ]}
    ]},
    { t: "art", n: 100, ep: "De las empresas del transporte nacional e internacional", b: [
      { p: `La prestación del servicio nacional de transporte terrestre público y privado, de personas y de carga, se reserva para los venezolanos y las venezolanas y para los extranjeros y las extranjeras residentes. Las empresas extranjeras de transporte terrestre autorizadas para prestar el servicio de transporte terrestre internacional, no podrán realizar transporte nacional o local, así como tampoco las personas jurídicas constituidas por ellos.` },
      { p: `En los casos de extranjeros o extranjeras o residentes que aspiren a prestar el servicio nacional o local personalmente o a través de sociedades de cualquier naturaleza, basados en tratados o convenios internacionales de los cuales la República Bolivariana de Venezuela sea parte, se aplicará la igualdad y equidad que de manera efectiva, tanto de hecho como de derecho, se otorgue a los venezolanos y venezolanas en los países signatarios de estos tratados o convenios internacionales.` },
      { p: `Sin perjuicio de la actuación de oficio por parte de la Administración, las autoridades competentes, a instancia de los y las particulares interesados e interesadas, deberán abrir los procesos correspondientes a los fines de verificar y decidir sobre los asuntos atinentes a esta materia.` }
    ]},
    { t: "cap", num: "III", nombre: "De los Permisos" },
    { t: "art", n: 101, ep: "Otorgamiento de permisos", b: [
      { p: `Las autoridades administrativas nacionales y municipales o metropolitanas, en sus respectivas jurisdicciones, son los órganos facultados para expedir:` },
      { ol: [
        `Permisos o autorizaciones de transporte de personas y de carga.`,
        `Certificaciones de prestación del servicio de transporte terrestre público de personas.`,
        `Tarjeta de identificación del operador u operadora.`,
        `Tarjeta de identificación vehicular y certificado de habilitación vehicular.`,
        `Certificaciones y licencias de operación para servicios conexos nacionales, estadales o municipales, según el caso.`,
        `Los demás instrumentos inherentes al Sistema Nacional de Transporte Terrestre.`
      ]},
      { p: `Para el otorgamiento de los actos previstos en el presente artículo se deben cumplir con los requisitos y condiciones establecidos en el reglamento de esta Ley.` }
    ]},
    { t: "art", n: 102, ep: "De la nulidad de los permisos", b: [
      { p: `Los actos administrativos a que se contrae el artículo anterior serán nulos al ser dictados con prescindencia total o parcial de los requisitos de validez previstos en esta Ley.` }
    ]},
    { t: "art", n: 103, ep: "Seguridad jurídica para los empresarios y las empresarias del transporte", b: [
      { p: `Las autoridades administrativas competentes, en el ámbito de su jurisdicción sólo podrán otorgar los instrumentos indicados en el artículo 98 de esta Ley, conforme a los planes de transporte y los estudios correspondientes, considerando la oferta y demanda del servicio de que se trate, la capacidad y calidad de los mismos.` }
    ]},
    { t: "cap", num: "IV", nombre: "Del Servicio de Transporte Terrestre de Personas" },
    { t: "art", n: 104, ep: "Prestación del servicio transporte terrestre público", b: [
      { p: `El servicio de transporte terrestre público colectivo en rutas urbanas, suburbanas e interurbanas será prestado, previa autorización otorgada por la autoridad competente, según el caso, por personas jurídicas cuyo objeto social principal sea el transporte terrestre público en la modalidad respectiva, de conformidad con lo previsto en la ley.` }
    ]},
    { t: "art", n: 105, ep: "Personas que podrán prestar el servicio", b: [
      { p: `El servicio de transporte terrestre público de pasajeros y pasajeras, previo al cumplimiento de las formalidades de la ley, podrá ser prestado:` },
      { ol: [
        `Directamente por la autoridad administrativa competente.`,
        `Por intermedio de personas jurídicas debidamente autorizadas por la autoridad administrativa competente.`,
        `Por intermedio de personas naturales en la modalidad individual.`
      ]},
      { p: `Parágrafo Único: Todos los conductores y conductoras que presten el servicio público de transporte terrestre de pasajeros y pasajeras, y de carga deberán haber aprobado el curso especial gratuito y haber obtenido el Certificado de Conducir, que los capacite para brindar tal servicio dictado por el Instituto Nacional de Transporte Terrestre o por escuela del transporte.` }
    ]},
    { t: "art", n: 106, ep: "Uso de terminales", b: [
      { p: `Las personas jurídicas autorizadas para prestar el servicio de transporte terrestre público de personas, en rutas interurbanas deben tener como punto de origen, toques intermedios y destino, un terminal de transporte terrestre público o privado, inscrito en el registro de terminales de transporte terrestre.` },
      { p: `Cuando se trate de la prestación del servicio en rutas urbanas o suburbanas, las características de la demanda, del uso del suelo y del tránsito, determinarán su operación a través de terminales públicos o privados.` }
    ]},
    { t: "art", n: 107, ep: "Cambio de uso", b: [
      { p: `Sólo los vehículos destinados a la prestación del servicio de transporte terrestre, público o privado de personas, son susceptibles de uso particular, excluyendo los vehículos adquiridos con incentivos fiscales.` }
    ]},
    { t: "art", n: 108, ep: "Derechos del pasajero y pasajera", b: [
      { p: `Los usuarios y las usuarias tienen derecho a:` },
      { ol: [
        `Un servicio de buena calidad.`,
        `Que se les fije una tarifa acorde con el servicio que reciben.`,
        `Exigir un servicio higiénico, seguro, confortable e ininterrumpido.`,
        `Recibir información oportuna sobre las condiciones de prestación del servicio de transporte terrestre público.`,
        `Recibir atención especial en caso de discapacidad, de niños o niñas con edad hasta seis (6) años, personas mayores de sesenta (60) años de edad, y mujeres en estado de gravidez o personas con niños o niñas en etapa de lactancia.`
      ]},
      { p: `Las normas de atención especial se establecerán en el Reglamento de esta Ley. El pasajero o la pasajera podrán hacer valer sus derechos conforme a los procedimientos establecidos en el Título VIII de esta Ley.` }
    ]},
    { t: "art", n: 109, ep: "Reparación por incumplimientos", b: [
      { p: `Los usuarios y las usuarias tienen derecho a ser resarcidos o resarcidas por los incumplimientos de los operadores o las operadoras del servicio del transporte terrestre público de personas y servicios conexos.` }
    ]},
    { t: "art", n: 110, ep: "Deberes del usuario y de la usuaria", b: [
      { p: `Los usuarios y las usuarias tienen el deber de:` },
      { ol: [
        `Pagar los cargos por los servicios recibidos de las personas autorizadas o concesionadas para prestarlos.`,
        `Informar al prestador o prestadora del servicio y a la autoridad competente sobre las deficiencias o daños ocurridos en las instalaciones y unidades del servicio.`,
        `Respetar las normas de comportamiento moral y buenas costumbres, establecidas, así como cuidar y mantener en buen estado las instalaciones y unidades del servicio.`
      ]}
    ]},
    { t: "cap", num: "V", nombre: "De la Clasificación de las Rutas de Transporte Terrestre Público" },
    { t: "art", n: 111, ep: "Clasificación de las rutas", b: [
      { p: `A los efectos de la presente Ley, las rutas de transporte terrestre público de pasajeros y de pasajeras se clasifican en urbanas, suburbanas e interurbanas. Estas a su vez podrán ser:` },
      { lv: [
        [0, `Urbanas:`],
        [1, `a. Municipales`],
        [1, `b. Intermunicipales`],
        [0, `Suburbanas:`],
        [1, `a. Municipales`],
        [1, `b. Intermunicipales`],
        [1, `c. Interestadales`],
        [0, `Interurbanas:`],
        [1, `a. Nacionales`],
        [1, `b. Estadales`],
        [1, `c. Municipales`]
      ]}
    ]},
    { t: "art", n: 112, ep: "Rutas urbanas", b: [
      { p: `A los efectos de esta Ley son rutas urbanas aquellas cuyo origen y destino se encuentran dentro de la poligonal urbana del municipio de que se trate, de conformidad con la ley que rige la materia.` },
      { p: `A los efectos de esta Ley son rutas urbanas intermunicipales aquellas que se desarrollan dentro de una poligonal metropolitana perteneciente a dos (2) o más municipios, y su recorrido se realiza entre ellos, cuya longitud, características y áreas de influencia se establecen en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 113, ep: "Rutas suburbanas", b: [
      { p: `A los efectos de esta Ley son rutas suburbanas aquellas que tienen su origen dentro de la poligonal urbana y se extienden fuera de ésta hasta poblaciones próximas o contiguas a dicha poligonal, cuya longitud, características y áreas de influencia se establecen en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 114, ep: "Rutas interurbanas", b: [
      { p: `A los efectos de esta Ley son rutas interurbanas aquellas que tienen su origen en una ciudad o centro poblado y su destino en otra, independientemente que se encuentre en jurisdicción de uno o más municipios o en una o más entidades federales, cuya longitud, características y áreas de influencia se establecen en el Reglamento de esta Ley.` }
    ]},
    { t: "cap", num: "VI", nombre: "De las Modalidades del Servicio de Transporte Terrestre Público" },
    { t: "art", n: 115, ep: "Modalidad colectivo", b: [
      { p: `A los efectos de esta Ley, el servicio de transporte terrestre público de personas, modalidad colectivo, es el prestado por personas jurídicas con unidades de alta, mediana y baja capacidad o por puesto, de conformidad con lo establecido en el Reglamento de esta Ley y las Normas del Sistema Nacional de Calidad.` }
    ]},
    { t: "art", n: 116, ep: "Sujeción de la modalidad colectivo", b: [
      { p: `El servicio modalidad colectivo debe estar sujeto a rutas, horarios y frecuencias, conforme a los permisos correspondientes emitidos por la autoridad competente y de acuerdo a lo establecido en esta Ley y su Reglamento.` }
    ]},
    { t: "art", n: 117, ep: "Modalidad individual", b: [
      { p: `El servicio de transporte terrestre público de personas, modalidad individual, es aquel donde el usuario y la usuaria fija el lugar de destino y se realiza sin sujeción a rutas. Las características y tipología de las unidades, incluyendo los taxis y moto taxis, serán las establecidas en las Normas del Sistema Nacional de Calidad. Las condiciones y requisitos para otorgar la autorización del servicio se establecerán en el Reglamento de esta Ley.` },
      { p: `Queda prohibido el uso de vehículos destinados al transporte terrestre público de personas, modalidad individual, para prestar el servicio en la modalidad colectivo y viceversa.` }
    ]},
    { t: "art", n: 118, ep: "Condiciones de la suspensión, revocación y extinción de la certificación de prestación del servicio", b: [
      { p: `Sin perjuicio de lo previsto en el ordenamiento jurídico municipal o estadal, son causales de suspensión, revocatoria o extinción de la certificación de prestación del servicio de la unidad de transporte inpeccionada, las siguientes:` },
      { lv: [
        [0, `Suspensión hasta tanto sean subsanadas las causas, previa nueva inspección:`],
        [1, `a. Neumáticos en malas condiciones.`],
        [1, `b. Sistema de luces internas y externas sin funcionamiento.`],
        [1, `c. Parabrisas, vidrios y espejos retrovisores, en mal estado.`],
        [1, `d. Sistema de frenos y dirección en mal estado.`],
        [1, `e. Cuando los asientos no reúnan los requisitos mínimos de seguridad, comodidad e higiene.`],
        [0, `Suspensión por tres (3) meses:`],
        [1, `a. Cuando el prestador o prestadora del transporte opere en zonas o rutas distintas a las autorizadas.`],
        [1, `b. Cuando el prestador o prestadora aumente las tarifas establecidas por el órgano competente.`],
        [1, `c. Cuando el prestador o prestadora incumpla con cualquiera de las obligaciones y condiciones previstas en la certificación de prestación del servicio.`],
        [0, `Revocatoria:`],
        [1, `a. Cuando resulten alteradas en cualquier forma, las condiciones bajo las cuales se otorga la certificación.`],
        [1, `b. Cuando se compruebe que para la obtención de la certificación o para el mantenimiento de la misma, el prestador o prestadora del servicio hubiere hecho uso de medios fraudulentos, o se compruebe falsedad de los documentos.`],
        [1, `c. Cuando el prestador o prestadora abandone la rutas autorizadas o suspenda el servicio, sin previa autorización, durante treinta (30) días consecutivos.`],
        [1, `d. Cuando el prestador o prestadora del servicio hubiere suspendido tres (3) veces en el término de dos (2) años.`],
        [0, `Extinción de la certificación:`],
        [1, `a. Por renuncia de la prestación del servicio, en forma escrita a las autoridades competentes;`],
        [1, `b. Por la muerte o incapacidad jurídica del prestador o prestadora del servicio, si fuere persona natural.`],
        [1, `c. Por la quiebra o liquidación de la persona jurídica.`],
        [1, `d. Por la no renovación de la certificación a su vencimiento.`],
        [1, `e. Por la revocatoria de la certificación.`]
      ]}
    ]},
    { t: "cap", num: "VII", nombre: "De las Modalidades del Transporte Privado" },
    { t: "art", n: 119, ep: "Modalidad estudiantil", b: [
      { p: `El servicio de transporte terrestre privado de personas modalidad estudiantil, es el prestado a los y las estudiantes de los establecimientos educativos públicos o privados, por cuenta propia o por terceros, previamente autorizados por la autoridad administrativa competente, cuyos vehículos cumplan con las Normas del Sistema Nacional de Calidad. Las condiciones y requisitos de la prestación del servicio serán establecidos en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 120, ep: "Modalidad turística", b: [
      { p: `El servicio de transporte terrestre privado de personas, modalidad turística, es aquel que se realiza hacia o desde lugares de interés turístico y cultural, con reiteración o no de itinerario, calendario y horario, sin rutas definidas, y con unidades adecuadas a todas las normas de seguridad y comodidad, conforme al tipo de servicio prestado, de acuerdo a lo establecido en las Normas del Sistema Nacional de Calidad y lo previsto en esta Ley.` }
    ]},
    { t: "art", n: 121, ep: "Servicio de transporte turístico extranjero", b: [
      { p: `Las unidades de servicio de transporte privado de personas, modalidad turística extranjera, que entren y circulen en el territorio nacional, gozarán del mismo trato, privilegios o prerrogativas que se le otorgue al venezolano o venezolana, conforme a los acuerdos o los tratados internacionales suscritos por la República.` }
    ]},
    { t: "art", n: 122, ep: "Modalidad personal", b: [
      { p: `El servicio de transporte terrestre privado de personas modalidad personal, es el que prestan las personas naturales o jurídicas u organismos públicos o privados, por cuenta propia o de terceros debidamente autorizados, en rutas previamente acordadas entre las partes.` }
    ]},
    { t: "art", n: 123, ep: "Modalidad alquiler de vehículos con o sin chofer", b: [
      { p: `El servicio de transporte terrestre privado de alquiler de vehículos con o sin conductores o conductoras, es el que prestan personas jurídicas, cumpliendo lo previsto en esta Ley y su Reglamento.` }
    ]},
    { t: "cap", num: "VIII", nombre: "Del Servicio de Transporte Automotor Terrestre de Carga" },
    { t: "art", n: 124, ep: "Prestación del servicio del transporte de carga", b: [
      { p: `El servicio de transporte automotor de carga general, a granel, perecedera y frágil, será prestado en los términos y condiciones previstos en la ley y las Normas del Sistema Nacional de Calidad.` }
    ]},
    { t: "art", n: 125, ep: "Personas que prestan el servicio", b: [
      { p: `El servicio de transporte automotor de carga general, a granel, perecedera y frágil será prestado por personas naturales o jurídicas debidamente autorizadas, según lo dispuesto en la ley.` },
      { p: `Las personas naturales propietarias de más de tres (3) vehículos en esta modalidad, deben constituirse en personas jurídicas para prestar este servicio.` }
    ]},
    { t: "art", n: 126, ep: "Carga de alto riesgo", b: [
      { p: `A los efectos de esta Ley, es carga de alto riesgo aquella compuesta de productos peligrosos, que por sus características, causen daños a las personas, medio ambiente, vehículos y demás bienes. Se incluyen dentro de las cargas de alto riesgo aquellas cuyas dimensiones o pesos superen el máximo establecido en las Normas del Sistema Nacional de Calidad.` }
    ]},
    { t: "art", n: 127, ep: "Clasificación del servicio", b: [
      { p: `A los fines de esta Ley, el transporte terrestre automotor de carga se clasifica en:` },
      { ol: [
        `De uso público, el prestado por personas naturales o jurídicas, debidamente acreditadas por la autoridad administrativa competente, recibiendo como contraprestación del servicio un flete.`,
        `De uso particular, el prestado por persona natural o jurídica, debidamente acreditada por la autoridad administrativa competente, para su propio y exclusivo uso.`
      ]}
    ]},
    { t: "art", n: 128, ep: "Certificación para prestar el servicio", b: [
      { p: `Toda persona natural o jurídica para prestar el servicio de transporte terrestre de carga, debe estar autorizada por el Instituto Nacional de Transporte Terrestre, previo cumplimiento de las condiciones y requisitos exigidos en la ley.` },
      { p: `El o la solicitante de la certificación de transporte de carga, deberá tener en propiedad uno o más vehículos, sin perjuicio a que incremente su flota mediante arrendamiento o cualquier otra figura jurídica.` }
    ]},
    { t: "art", n: 129, ep: "Generadores y equipos de control de carga", b: [
      { p: `Las autoridades de puertos y aeropuertos, públicos y privados, las industrias siderúrgicas, metalmecánica, eléctricas, electrónicas, química, petroquímica, petrolera y gasífera, así como cualquier otra actividad que genere carga, incluyendo las de alto riesgo, transportadas por vías terrestre, deben establecer los sistemas de pesajes correspondientes en los puntos de origen del transporte, a objeto de ajustar las cargas a los límites permitidos, conforme a lo establecido en las Normas del Sistema Nacional de Calidad en materia de transporte terrestre.` },
      { p: `Los equipos de pesajes utilizados para el control de peso a que se refiere este artículo deben estar calibrados, y demostrar anualmente la idoneidad de sus sistemas ante el órgano rector competente, de conformidad con la ley que rige la materia.` },
      { p: `Colocar el sistema de pesas en los puentes a nivel nacional.` }
    ]},
    { t: "art", n: 130, ep: "Prestación del servicio de carga de alto riesgo", b: [
      { p: `El servicio de transporte terrestre de carga de alto riesgo podrá prestarse tanto por el Ejecutivo Nacional, a través de sus órganos competentes, como por las personas jurídicas autorizadas, de conformidad con esta ley.` }
    ]},
    { t: "art", n: 131, ep: "Características del servicio carga de alto riesgo", b: [
      { p: `Todo servicio de transporte terrestre de carga de alto riesgo, debe realizarse en vehículos construidos, acondicionados y mantenidos de acuerdo a la naturaleza de la carga a transportar, de conformidad con las Normas del Sistema Nacional de Calidad, en materia de transporte terrestre, así como en lo establecido en esta Ley.` }
    ]},
    { t: "art", n: 132, ep: "Examen para la conducción de vehículos con cargas de alto riesgo y sobredimensionados", b: [
      { p: `En el Reglamento de esta Ley se establecerán los requisitos y condiciones, así como la obligación de realizar y aprobar cursos y exámenes para la conducción de vehículos destinados al transporte de carga de alto riesgo, de acuerdo a la naturaleza de la carga, y los sobredimensionados.` }
    ]},
    { t: "cap", num: "IX", nombre: "De los Servicios Conexos al Transporte Terrestre" },
    { t: "art", n: 133, ep: "Definición y tipos de servicios conexos", b: [
      { p: `Se entiende por servicios conexos al transporte terrestre, aquellas actividades que complementen el transporte, y sólo podrán ser prestados con la previa autorización de la autoridad competente, y bajo las normas de funcionamiento aplicables en cada caso.` },
      { p: `Se consideran servicios conexos:` },
      { ol: [
        `Peritajes y experticias de vehículos.`,
        `Terminales de pasajeros y pasajeras, y de carga, públicos o privados.`,
        `Paradores viales de pasajeros y pasajeras, turístico y carga.`,
        `Transporte de encomiendas.`,
        `Escuela del transporte.`,
        `Estacionamientos de recepción, guarda, custodia, conservación y entrega de aquellos vehículos causantes de infracciones a la presente Ley, o por accidentes de transporte terrestre.`,
        `Estaciones de servicio de expendio de combustible.`,
        `Estaciones fijas y móviles de control de carga.`,
        `Talleres mecánicos cuya actividad deba ser reconocida a los efectos de la revisión técnica de vehículos.`,
        `Estaciones fijas y móviles de revisión técnica, mecánica y física de vehículos.`,
        `Centros de componentes automotrices usados.`,
        `Servicios de grúa de arrastre y de plataforma.`,
        `Centros de reciclaje de componentes automotrices usados.`,
        `Cualesquiera otros que se prevean en el Reglamento de esta Ley.`
      ]}
    ]},
    { t: "art", n: 134, ep: "Estudios requeridos en servicios conexos", b: [
      { p: `Las autoridades competentes deben exigir los estudios de impacto ambiental y vial a los proyectos destinados para la construcción de los servicios conexos al transporte terrestre, cuyos requisitos se establecerán en el Reglamento de esta Ley, en concordancia con las leyes que rigen la materia.` }
    ]},
    { t: "art", n: 135, ep: "Competencia en los servicios de terminales públicos de pasajeros y pasajeras", b: [
      { p: `El Ejecutivo Estadal, Municipal o Metropolitano, en sus respectivas jurisdicciones, proyectarán, construirán, administrarán, operarán, mantendrán y explotarán los terminales públicos de pasajeros y pasajeras urbanos, municipales o intermunicipales, cumpliendo con lo establecido en la presente Ley y su Reglamento.` },
      { p: `En aquellos casos en los cuales se establezcan servicios de transporte terrestre público estadales, corresponderá a la respectiva autoridad estadal proyectar, construir, operar, mantener y explotar el terminal que al efecto se prevea, pudiendo otorgar la respectiva licencia de operación.` }
    ]},
    { t: "art", n: 136, ep: "Suspensión y revocación de la licencia de operación", b: [
      { p: `El Instituto Nacional de Transporte Terrestre suspenderá la licencia de operación del terminal de pasajeros y pasajeras como servicio conexo, cuando sus administradores incurran en algunas de las siguientes causales:` },
      { ol: [
        `No haber cumplido con el registro de la infraestructura como servicio conexo, por ante ministerio del poder popular con competencia en materia de transporte terrestre por órgano del Instituto Nacional de Transporte Terrestre.`,
        `Por no cumplir con los requerimientos mínimos de servicio y de operatividad del terminal, debido a una deficiente administración.`
      ]},
      { p: `La suspensión se mantendrá hasta tanto sean subsanadas las causas que la motivaron, previa nueva inspección. La licencia de operación del terminal de pasajeros y pasajeras será revocada cuando sus administradores incurran en alguna de las siguientes causales:` },
      { ol: [
        `Haberle dado un uso diferente a la infraestructura, según lo establecido en esta Ley y su Reglamento.`,
        `Carencia de orden interno en la operación del terminal, que ponga en riesgo a los usuarios y las usuarias del servicio, imputable al administrador o administradora del terminal.`,
        `Reiterada negativa a suministrar información sobre la gestión del terminal.`
      ]},
      { p: `Para la revocación de la licencia de operación del terminal de pasajeros y pasajeras se aplicará el procedimiento administrativo que rige la materia.` }
    ]},
    { t: "art", n: 137, ep: "Servicios conexos sobre la vialidad nacional", b: [
      { p: `El ministerio del poder popular con competencia en materia de transporte terrestre, en coordinación con el Ejecutivo Estadal, aprobará los proyectos de servicios conexos de las áreas de servicios viales y de instalaciones de servicios públicos en autopistas y carreteras nacionales para el transporte terrestre automotor de personas y de carga, tomando en consideración la ubicación, características operativas y viales, cuyas normas y requisitos se establecen en el Reglamento de esta Ley, en concordancia con el ordenamiento jurídico que rige la materia.` }
    ]},
    { t: "art", n: 138, ep: "Ubicación, supervisión y control de los paradores viales", b: [
      { p: `El Instituto Nacional de Transporte Terrestre coordinará con los gobiernos municipales la ubicación, supervisión y control de los paradores viales para el transporte terrestre automotor de carga, pasajeros y pasajeras, y turístico.` }
    ]},
    { t: "art", n: 139, ep: "Certificación de terminales de transferencia e inter modales de carga", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es el ente encargado de otorgar certificación del proyecto, registro de servicio y certificado de operación de servicios conexos de los terminales generadores, transferencia e inter modales de carga, tomando en consideración la ubicación, características operativas y viales, cuyas normas y requisitos se establecen en el Reglamento de esta Ley en concordancia con el ordenamiento jurídico que rige la materia.` }
    ]},
    { t: "art", n: 140, ep: "Permiso para operar como escuela del transporte", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es el ente encargado de autorizar a las personas jurídicas e instituciones educativas para operar como escuela del transporte, mediante la licencia de operación de servicio conexo, así como ejercer su supervisión y control, todo lo cual se establecerá en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 141, ep: "Instructores e instructoras de la escuela del transporte", b: [
      { p: `Las escuelas del transporte contarán con instructores o instructoras debidamente autorizados por el Instituto Nacional de Transporte Terrestre, mediante la aprobación del curso correspondiente, de conformidad con lo establecido en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 142, ep: "Regulación y permiso de los estacionamientos", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es el ente encargado de regular, supervisar, controlar, otorgar y revocar los certificados de operación de servicios conexos de los estacionamientos para la guarda y custodia de vehículos, a la orden o procesados por las autoridades administrativas de transporte u otras autoridades competentes.` },
      { p: `Las actividades de supervisión de funcionamiento serán ejecutadas en coordinación con el Cuerpo Técnico de Vigilancia de Transporte Terrestre.` },
      { p: `Los requisitos para la obtención del certificado de operación de servicio conexo de los estacionamientos, así como las causales de suspensión y revocatoria serán establecidos en el Reglamento de esta Ley.` }
    ]},
    { t: "cap", num: "X", nombre: "Del Régimen Tarifario" },
    { t: "art", n: 143, ep: "Fijación y regulación de las tarifas del transporte terrestre público de pasajeros y pasajeras", b: [
      { p: `El ministerio del poder popular con competencia en materia de transporte terrestre por órgano del Instituto Nacional de Transporte Terrestre, conjuntamente con el ministerio del poder popular con competencia en materia de industrias ligeras y comercio, fijarán, regularán y publicarán, en el primer trimestre del año, las tarifas correspondientes a los servicios de transporte terrestre público de personas, en las rutas urbanas, suburbanas e interurbanas de su competencia, basándose en estudios de transporte de orden técnico, económico, financiero y en la calidad del servicio que se preste con la participación de los sectores involucrados.` },
      { p: `Los estudios de transporte para la fijación de las tarifas, serán analizados y establecidos anualmente, durante el cuarto trimestre, y deberán ser remitidas al Instituto Nacional de Transporte Terrestre por cada organización, para su revisión y análisis.` }
    ]},
    { t: "art", n: 144, ep: "Métodos y procedimientos básicos a ser aplicados en la fijación de tarifas para el servicio de transporte terrestre público de pasajeros y pasajeras", b: [
      { p: `El ministerio del poder popular con competencia en materia de transporte terrestre por órgano del Instituto Nacional de Transporte Terrestre, establecerán los métodos y procedimientos básicos a ser aplicados en la fijación de tarifas para el servicio de transporte terrestre público de pasajeros y pasajeras.` }
    ]},
    { t: "art", n: 145, ep: "Las autoridades competentes", b: [
      { p: `Las autoridades municipales, mancomunadas y metropolitanas fijarán, regularán y publicarán, en el primer trimestre del año, las tarifas a ser cobradas en el servicio de transporte terrestre público de pasajeros y pasajeras en las rutas correspondientes a su jurisdicción, oída la opinión de los Consejos Comunales e interesados en la materia.` }
    ]},
    { t: "art", n: 146, ep: "Fijación de las tarifas de los servicios en los terminales públicos", b: [
      { p: `Los entes públicos que administren los terminales públicos de pasajeros y pasajeras, fijarán las tarifas a cobrar por concepto de los servicios prestados a sus usuarios y usuarias, y por la explotación comercial de áreas dentro de los terminales; el producto de dichas tarifas deberá ser utilizado para la conservación, mantenimiento y seguridad de tales terminales, con la supervisión del Instituto Nacional de Transporte Terrestre, a los efectos de que cumplan con la retribución de los servicios en función de las tarifas cobradas.` }
    ]},
    { t: "art", n: 147, ep: "Tarifas en el transporte de carga", b: [
      { p: `El servicio de transporte terrestre de carga no estará sometido a un régimen tarifario regulado. El ministerio del poder popular con competencia en materia de transporte terrestre, conjuntamente con el ministerio del poder popular con competencia en materia de industrias ligeras y comercio, cuando lo consideren pertinente y se trate del transporte de bienes decretados como de primera necesidad o estratégicos, fijarán las tarifas a cobrar en el territorio nacional, apoyándose en una metodología tarifaria con sus respectivos estudios de transporte.` }
    ]},
    { t: "art", n: 148, ep: "Fijación de tarifas por concepto de remolque, guarda y custodia", b: [
      { p: `El Instituto Nacional de Transporte Terrestre es competente para fijar las tarifas a ser cobradas en todo el territorio nacional, por concepto de remolque de vehículos según tipología y por el servicio de estacionamientos para la guarda y custodia de vehículos a la orden o procesados por las autoridades competentes.` }
    ]},
    { t: "art", n: 149, ep: "Obligación de mantener a la vista las tarifas", b: [
      { p: `Las personas jurídicas prestatarias de los servicios de transporte terrestre y de servicios conexos, están obligadas a colocar en lugares visibles al público, las tarifas establecidas, tanto en los espacios como en los vehículos donde se presten estos servicios conexos.` }
    ]},
    { t: "titulo", num: "VI", nombre: "De la Infraestructura Vial" },
    { t: "cap", num: "I", nombre: "Disposiciones Generales" },
    { t: "art", n: 150, ep: "Cuerpo de normas y procedimientos técnicos", b: [
      { p: `Los estados y los municipios al realizar un proyecto de vialidad se sujetarán a las normas y procedimientos técnicos y administrativos, que a tales efectos dicte el ministerio del poder popular con competencia en materia de transporte terrestre.` }
    ]},
    { t: "art", n: 151, ep: "Derecho de vía", b: [
      { p: `A los efectos de esta Ley, se entiende por derecho de vía, la franja de terreno, medida en proyección horizontal y perpendicular al eje de la vía, en ambos lados en forma continua destinada a la construcción, ampliación, conservación, mantenimiento, seguridad, inspección de elementos estructurales o de funcionamiento, ubicación de instalación de servicios públicos e implantación de rampas de incorporación o desincorporación de servicios viales y apoyo a transportes masivos.` },
      { p: `Las especificaciones referentes para la determinación de las distancias mínimas en las vías públicas se establecerán en el Reglamento de esta Ley, conforme a las características de cada vía.` }
    ]},
    { t: "art", n: 152, ep: "Vías nacionales", b: [
      { p: `Se declaran vías de comunicación nacionales:` },
      { ol: [
        `Las carreteras que atraviesen un estado y salgan de sus límites.`,
        `Las carreteras que atraviesen el Distrito Metropolitano de Caracas y salgan de sus límites.`,
        `Los puentes que formen parte de las carreteras antes indicadas aunque se encuentren dentro de los límites de un estado.`,
        `Las autopistas incluyendo sus distribuidores, puentes, túneles, viaductos y rampas de accesos, aunque se encuentren dentro de los límites de un estado.`,
        `Las incluidas en los acuerdos internacionales celebrados por la República, las que pertenezcan al sistema vial estratégico fronterizo, de seguridad y defensa nacional.`,
        `Las que sirven de acceso a otros modos de transporte y las de conexión nacional e internacional.`,
        `Las que además de servir al tráfico local o estadal, sirven al tráfico nacional e internacional.`
      ]}
    ]},
    { t: "art", n: 153, ep: "Vías estadales", b: [
      { p: `Son vías de comunicación estadales las que constituyen la red vial dentro de cada estado, con exclusión de las vías de comunicación nacionales que se encuentren en el mismo.` }
    ]},
    { t: "art", n: 154, ep: "Autorización dentro del derecho de vía", b: [
      { p: `Toda construcción, reparación, instalación de servicios públicos y conexos y demás actividades que se ejecuten dentro de la franja de derecho de vía de las vías nacionales, por parte de entes públicos o privados, requerirá la aprobación del ministerio del poder popular con competencia en materia de transporte terrestre.` }
    ]},
    { t: "art", n: 155, ep: "Obligación de reparar", b: [
      { p: `Los organismos públicos o privados autorizados para realizar trabajos de empotramiento o instalación de servicios públicos en las vías, deberán dejarlas en iguales o mejores condiciones de la que tenían antes de su intervención, todo ello de conformidad con lo previsto en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 156, ep: "Vías alternas", b: [
      { p: `El Poder Público Nacional garantizará a los usuarios y las usuarias el libre tránsito por la red vial explotada mediante el régimen de concesión o administración directa.` },
      { p: `Son vías alternas aquellas que se construyen, mantienen y amplían por las autoridades competentes, en aquellos casos en que hayan otorgado una autopista o carretera en concesión, con la finalidad de garantizar que los usuarios y las usuarias puedan ejercer su derecho al libre tránsito, sin tener que pagar a cambio contraprestación alguna.` }
    ]},
    { t: "cap", num: "II", nombre: "De las Competencias" },
    { t: "art", n: 157, ep: "Competencia nacional", b: [
      { p: `Corresponde al ministerio del poder popular con competencia en materia de transporte terrestre el control, inspección y supervisión, la elaboración de las normas técnicas y administrativas para la construcción, mantenimiento, aprovechamiento de todo el sistema de vialidad nacional y en especial la fijación de los criterios para la determinación de las tarifas de peaje nacional.` },
      { p: `Cuando se trate de excedentes viales afectados, expropiados o adscritos por causa de utilidad pública, será competencia del ministerio del poder popular con competencia en materia de transporte terrestre la gestión administrativa sobre el uso de estos bienes inmuebles, aprobar los estudios de factibilidad de construcción de obras en las franjas de derecho de vía y, otras que determine la ley.` }
    ]},
    { t: "art", n: 158, ep: "Coordinación nacional y estadal", b: [
      { p: `Es de la competencia del ministerio del poder popular con competencia en materia de transporte terrestre en coordinación con los estados, la conservación, administración y aprovechamiento de la vialidad nacional, incluyéndose las obras de artes que las integran. A tales efectos, los estados deberán dar cumplimiento al cuerpo de normas y procedimientos técnicos y administrativos, establecidos por el ministerio del poder popular con competencia en materia de transporte terrestre y además, hacer del conocimiento de los planes de conservación y actividades de mantenimiento, de operatividad, así como los planes de contingencia anualmente.` }
    ]},
    { t: "art", n: 159, ep: "Inventario de las características físicas de la red vial", b: [
      { p: `El ministerio del poder popular con competencia en materia de transporte terrestre conjuntamente con los estados deberá mantener actualizado, el inventario de la red vial y el nomenclador vial del territorio nacional, a los fines de su incorporación al Registro Nacional de Transporte.` }
    ]},
    { t: "art", n: 160, ep: "Actividades viales coordinadas con el Ejecutivo Nacional", b: [
      { p: `Corresponde al ministerio del poder popular con competencia en materia de transporte terrestre, en coordinación con los estados, en las vías terrestres nacionales:` },
      { ol: [
        `La ubicación, instalación, ordenamiento y calidad de los servicios de las estaciones de peajes nacionales.`,
        `La factibilidad técnica, económica y financiera de las concesiones viales.`,
        `Elaboración de los contratos de concesión de obras viales.`,
        `Resguardar los derechos de vía tanto nacionales como estadales.`,
        `Elaboración de manuales de conservación vial.`,
        `Otras que determine la ley.`
      ]}
    ]},
    { t: "art", n: 161, ep: "Competencia municipal", b: [
      { p: `Los municipios en el ámbito de su jurisdicción son competentes, para la ejecución, supervisión, inspección, mantenimiento de la infraestructura vial urbana, señalización y demarcación, incluyendo las paradas para el transporte terrestre público de personas, zonas de carga y áreas de estacionamiento, las estructuras de paso, tanto peatonal como vehicular, cumpliendo con los niveles de servicio y demás aspectos de seguridad vial establecidos en las normas y manuales, nacionales e internacionales, de obligatorio cumplimiento en la República Bolivariana de Venezuela.` }
    ]},
    { t: "art", n: 162, ep: "Coordinación en casos de contingencias", b: [
      { p: `El ministerio del poder popular con competencia en materia de transporte terrestre coordinará con los órganos competentes nacionales, estadales y municipales, la ejecución de los planes viales de contingencia que garanticen el tránsito inmediato por las vías y la recuperación de la infraestructura vial afectada en casos de desastres o emergencias.` }
    ]},
    { t: "cap", num: "III", nombre: "Administración de Vías Nacionales" },
    { t: "art", n: 163, ep: "Plan del sistema vial", b: [
      { p: `Cada entidad federal atendiendo al Plan de Desarrollo Económico y Social de la Nación, realizará su Plan del Sistema Vial que incluya las vías altamente potenciales a ser administradas.` }
    ]},
    { t: "art", n: 164, ep: "Concesiones de nuevas vías", b: [
      { p: `En el caso de concesiones para la construcción de autopistas y carreteras nacionales otorgadas por el ministerio del poder popular con competencia en materia de transporte terrestre; la competencia para la conservación, administración y aprovechamiento del tramo construido en dichas vías nacionales, podrá ser asumida por los estados, en sus respectivas jurisdicciones, al vencimiento del plazo de la concesión, de conformidad con lo establecido en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 165, ep: "Inspección de proyectos bajo concesión", b: [
      { p: `Las obras de vialidad otorgadas en concesión quedan sujetas a la inspección y normalización técnica del ministerio del poder popular con competencia en materia de transporte terrestre, el cual podrá ordenar la paralización o dictar medidas correctivas de aquellos proyectos cuya ejecución no se ajuste a los términos de obligatorio cumplimiento.` },
      { p: `El Instituto Nacional de Transporte Terrestre inspeccionará lo relativo a la estricta aplicación de las normas de transporte terrestre dentro de la referida vialidad.` }
    ]},
    { t: "art", n: 166, ep: "Uso de lo recaudado en las estaciones de peaje", b: [
      { p: `Los ingresos provenientes de la recaudación por concepto de peajes, deberán ser reinvertidos prioritariamente en la atención de las condiciones básicas de transitabilidad, tales como: seguridad, rehabilitación, mantenimiento preventivo y correctivo, demarcación, inspección y señalización de las vías que causen el pago, de las vías alternas y rurales de la entidad, así como, los gastos de administración de la estación recaudadora.` }
    ]},
    { t: "art", n: 167, ep: "Mancomunidades", b: [
      { p: `Los estados para fines de interés público, deben asociarse en mancomunidad cuando las vías nacionales, incluyendo puentes y túneles, bajo régimen de explotación, atraviesen el territorio de dos (2) o más estados, previendo en su constitución el régimen de administración aplicable. Cuando así fuere, se hará del conocimiento del ministerio del poder popular con competencia en materia de transporte terrestre.` }
    ]},
    { t: "art", n: 168, ep: "Estudio técnico - económico - financiero", b: [
      { p: `Los estados, para instalar o actualizar estaciones recaudadoras de peaje en las vías nacionales, deberán realizar un estudio técnico - económico - financiero, que justifique su ubicación y características, así como la determinación de las tarifas, el cual deberá presentarlo al ministerio del poder popular con competencia en materia de transporte terrestre, a los efectos de evaluar los estudios y otorgar la correspondiente factibilidad.` }
    ]},
    { t: "titulo", num: "VII", nombre: "De las Infracciones y Sanciones Administrativas y de la Responsabilidad de las Sanciones por Infracción" },
    { t: "cap", num: "I", nombre: "De las Infracciones y Sanciones Administrativas" },
    { t: "art", n: 169, ep: "Sanciones graves", b: [
      { p: `Serán sancionados o sancionadas con multas de diez unidades tributarias (10 U.T.), quienes incurran en las siguientes infracciones:` },
      { ol: [
        `Conducir vehículos sin haber obtenido la licencia o título profesional correspondiente.`,
        `Desatender las indicaciones de los semáforos.`,
        `Conducir vehículos sin haber aprobado la revisión técnica, mecánica y física de los mismos en la oportunidad debida.`,
        `Conducir vehículos sobrepasando el límite permitido de velocidad.`,
        `Conducir vehículos habiendo sobrepasado el tiempo máximo permitido de conducción para transporte terrestre público de personas y de carga.`,
        `Circular con vehículos de transporte terrestre público o privado de personas y de carga, por los canales de circulación no permitidos para tales vehículos.`,
        `Conducir vehículos estando incapacitado físicamente para ello.`,
        `Conducir vehículos bajo influencia de bebidas alcohólicas, sustancias estupefacientes o psicotrópicas.`,
        `Conducir vehículos poniendo en peligro la circulación de otros vehículos debidamente señalizados para ser usados por personas con discapacidad o en labores de enseñanza de conducción.`,
        `Conducir vehículos realizando maniobras prohibidas por el Reglamento de esta Ley o por la autoridad competente, en las vías de circulación.`,
        `Conducir vehículos desprovistos de los dispositivos de control, equipos o accesorios de uso obligatorio, relativos a las condiciones de seguridad o cuando dichos aditamentos presenten defectos de funcionamiento o no cumplan con las normas y demás características técnicas previstas en el Reglamento de esta Ley.`,
        `Conducir vehículos utilizando equipos de comunicación, con excepción del dispositivo de manos libres.`,
        `Conducir vehículos que no cumplan con las Normas del Sistema Nacional de Calidad, sin perjuicio de lo establecido en el Reglamento de esta Ley.`,
        `Suministrar datos falsos al Registro Nacional de Vehículos y de Conductores y Conductoras, y a las autoridades competentes que intervengan en los casos de infracciones a la presente Ley y en accidentes de tránsito.`,
        `Conducir vehículos de transporte terrestre público de personas o carga en cualquiera de sus modalidades, sin estar debidamente autorizado conforme a la ley.`,
        `Prestar el servicio de transporte terrestre de carga en cualquiera de sus modalidades, en unidades no aptas o en vías prohibidas para su circulación.`,
        `Ejecutar cualquier tipo de actividad o de trabajo que afecte la circulación y la seguridad del tránsito, sin los permisos correspondientes otorgados de acuerdo a lo previsto en el Reglamento de esta Ley.`,
        `Las personas que, en ejercicio de la autoridad administrativa, ordenen la colocación de señales y dispositivos de control de tránsito terrestre o efectúen demarcaciones, que no cumplan con las disposiciones nacionales e internacionales establecidas a tal efecto.`,
        `Dañen, alteren o sustraigan los dispositivos de control de tránsito; los coloquen o sustituyan sin permiso de la autoridad administrativa competente.`,
        `No hacer uso del cinturón de seguridad, ni velar porque los demás ocupantes del vehículo lo utilicen debidamente.`,
        `Los propietarios y las propietarias o conductores y conductoras que modifiquen o alteren los elementos y condiciones de seguridad de fabricación de los vehículos, sin la autorización correspondiente.`,
        `Los propietarios y las propietarias de vehículos de transporte terrestre público de personas y carga, que no tengan instalados los dispositivos y registro de velocidad, o ejecuten actos tendentes a eliminar o alterar su normal funcionamiento.`,
        `Los que se den a la fuga en caso de estar involucrados en accidentes de tránsito.`
      ]},
      { p: `Las multas previstas en el presente artículo serán aplicadas sin perjuicio de las demás sanciones o medidas administrativas previstas en esta Ley.` }
    ]},
    { t: "art", n: 170, ep: "Sanciones menos graves", b: [
      { p: `Serán sancionadas con multas de cinco Unidades Tributarias (5 U.T.), sin perjuicio de las sanciones establecidas en esta y otras leyes, quienes incurran en las siguientes infracciones:` },
      { ol: [
        `Circular sin placas identificadoras o con las placas que no correspondan al vehículo, o con diseños distintos a los establecidos por la autoridad competente.`,
        `No haber realizado el respectivo trámite del vehículo ante el Registro Nacional de Vehículos y de Conductores y Conductoras.`,
        `Circular con vehículos que no se encuentren amparados por pólizas de seguro vigente previstas en esta Ley.`,
        `Conducir vehículos que superen los límites permitidos por las normas sobre contaminación por fuentes móviles o por ruidos, sean estos últimos producidos directamente por el vehículo o por sus ocupantes.`,
        `Prestar el servicio de transporte terrestre de carga en cualquiera de sus modalidades, en días u horarios no permitidos.`,
        `Prestar servicios conexos sin estar autorizados conforme a esta Ley y su Reglamento.`,
        `Cobrar tarifas de servicio público de transporte terrestre de pasajeros y pasajeras no establecidas por la autoridad competente.`,
        `Excederse en el cobro de tarifas por concepto de remolque según tipología de vehículos o por el servicio de estacionamientos para la guarda y custodia de vehículos a la orden o procesados por las autoridades administrativas.`,
        `Las personas obligadas conforme a esta Ley y su Reglamento a notificar la desincorporación de vehículos del Registro Nacional de Vehículos y de Conductores y Conductoras.`,
        `Estacionar en lugares prohibidos por el Reglamento de esta Ley o en zonas demarcadas y señalizadas para vehículos y equipos de emergencia y prevención, u obstruir sus accesos.`,
        `Usar en los lugares destinados para la colocación de las placas identificadoras, placas o distintivos no autorizados o que obstruyan la visibilidad de las mismas.`,
        `Utilizar en los vehículos, que no sean calificados como de emergencia, luces, faros, sirenas, señales audibles u otros implementos que hagan presumir se trata de situaciones de emergencia, o induzcan a confusión a los demás usuarios y las usuarias de las vías públicas.`,
        `Transportar niños o niñas menores de diez (10) años de edad, en el asiento delantero del vehículo.`,
        `Reservarse sin autorización espacios de vía pública con fines personales o comerciales.`,
        `El exceso de personas en el servicio de transporte terrestre público y privado de pasajeros y pasajeras en las rutas que establezca el Reglamento de esta Ley.`,
        `Los conductores y conductoras de motocicletas que: a) Circulen entre canales o paralelamente a otro vehículo en movimiento, a más de sesenta kilómetros por hora (60 kph). b) Circulen cambiando frecuentemente de canal o pasando indistintamente al centro, a la izquierda o a la derecha de la vía. c) Transporten más de dos (2) personas. d) Transporten carga con peso mayor de noventa kilogramos (90 Kgs), a menos que estén especialmente acondicionadas para ello. e) Transporten carga u objetos cuyo volumen dificulte la conducción del vehículo. f) Circulen o estacionen por áreas destinadas para los peatones u otros modos no motorizados. g) Conduzcan en contra vía. h) No utilicen de los cascos o elementos de protección.`
      ]},
      { p: `Parágrafo Único: hasta tanto la autoridad competente en la materia no establezca en las autopistas y vías de circulación rápida un canal exclusivo para la circulación de motociclistas, estos deberán circular por el canal de hombrillo, quien contravenga esta disposición será sancionado o sancionada con cinco Unidades Tributarias (5 U.T.), de acuerdo a lo establecido en este artículo.` }
    ]},
    { t: "art", n: 171, ep: "Sanciones leves", b: [
      { p: `Serán sancionadas con multas de tres Unidades Tributarias (3 U.T.), sin perjuicio de las sanciones establecidas en esta y otras leyes, quienes incurran en las siguientes infracciones:` },
      { ol: [
        `Conducir vehículos con licencia o título profesional vencido, o no portarlo al serle requerido por la autoridad competente.`,
        `Conducir vehículos con el Certificado Médico de Salud Integral vencido, o no portarlo al serle requerido por la autoridad competente.`
      ]},
      { p: `Las infracciones a las normas previstas en esta Ley, su Reglamento o en las resoluciones que dicte el ministerio del poder popular con competencia en materia de transporte terrestre, relacionadas con las regulaciones generales y especiales de circulación de vehículos y peatones, que no tengan una sanción expresa, serán penadas con multas de tres Unidades Tributarias (3 U.T.).` }
    ]},
    { t: "art", n: 172, ep: "De las amonestaciones", b: [
      { p: `Los y las peatones, ciclistas y demás conductores y conductoras de vehículos de tracción a sangre que incumplan con las disposiciones de esta Ley, su Reglamento o en las resoluciones que dicte el ministerio del poder popular con competencia en materia de transporte terrestre, serán amonestados por el órgano de ejecución competente y deberán asistir a un curso formativo, conforme a lo indicado en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 173, ep: "Sanciones muy graves", b: [
      { p: `Los conductores y las conductoras de vehículos que efectúen competiciones de velocidad o "piques" en las vías públicas, serán sancionados o sancionadas con multa de cien Unidades Tributarias (100 U.T.), sin perjuicio de las demás sanciones penales o civiles correspondientes.` }
    ]},
    { t: "art", n: 174, ep: "Infracciones y sanciones a las personas jurídicas", b: [
      { p: `Serán sancionadas con multas, las personas jurídicas prestatarias del servicio de transporte terrestre de personas y de carga, que incurran o permitan a los conductores y las conductoras que operan bajo su responsabilidad, directamente o mediante la afiliación u otra forma jurídica de vinculación, la comisión de las siguientes infracciones:` },
      { ol: [
        `El exceso de velocidad, debidamente comprobado por medios técnicos, aprobados por el Instituto Nacional de Transporte Terrestre y adoptados por el Cuerpo Técnico de Vigilancia del Transporte Terrestre y las policías homologadas, el no cumplimiento con los tiempos de conducción y descanso establecidos en el Reglamento de esta Ley: con doscientas Unidades Tributarias (200 U.T.). La aplicación de seis (6) multas en los casos antes señalados, impuestas a conductores y conductoras de una misma persona jurídica en el lapso de seis (6) meses, conlleva la suspensión del respectivo permiso de prestación del servicio por el término de seis (6) meses.`,
        `El exceso de altura, longitud y ancho no autorizado en el servicio de transporte terrestre de carga, con cincuenta Unidades Tributarias (50 U.T.).`
      ]}
    ]},
    { t: "art", n: 175, ep: "Sanciones por exceso de carga", b: [
      { p: `Las personas naturales y jurídicas que en sus vehículos transporten exceso de carga, así como las empresas generadoras, de transferencia e intermodal de carga, según se compruebe la responsabilidad en cada caso, serán sancionadas de la siguiente manera:` },
      { ol: [
        `Exceso hasta diez toneladas (10 Tn.), multa de diez Unidades Tributarias (10 U.T.) por cada tonelada o fracción excedida.`,
        `Exceso superior a diez toneladas (10 Tn.), hasta veinte toneladas (20 Tn.), multa de veinte Unidades Tributarias (20 U.T.) por cada tonelada o fracción excedida.`,
        `Exceso superior a veinte toneladas (20 Tn.), hasta treinta toneladas (30 Tn.), multa de treinta Unidades Tributarias (30 U.T.) por cada tonelada o fracción excedida.`,
        `Exceso superior a treinta toneladas (30 Tn.) hasta cuarenta (40 Tn.) toneladas, multa de cuarenta Unidades Tributarias (40 U.T.) por cada tonelada o fracción excedida.`,
        `Exceso superior a cuarenta toneladas (40 Tn.) hasta cincuenta toneladas (50 Tn.), multa de sesenta Unidades Tributarias (60 U.T.) por cada tonelada o fracción excedida.`,
        `Exceso superior a las cincuenta (50 Tn.) toneladas, multa de cien Unidades Tributarias (100 U.T.) por cada tonelada o fracción excedida.`
      ]}
    ]},
    { t: "art", n: 176, ep: "Sanciones aplicables a conductores y conductoras de vehículos pertenecientes a entes de la administración pública", b: [
      { p: `Cuando alguna de las multas recaiga sobre el conductor o conductora de un vehículo adscrito o perteneciente a cualquier ente de la Administración Pública, la autoridad administrativa competente, además de velar por el inicio de proceso jurisdiccional del caso, informará a las autoridades respectivas la presunta infracción del conductor o conductora del vehículo propiedad de la Administración Pública.` }
    ]},
    { t: "art", n: 177, ep: "Reincidencia", b: [
      { p: `En caso de reincidencia, se duplicará el monto de la sanción.` }
    ]},
    { t: "art", n: 178, ep: "Excedente de pasajeros y pasajeras, y carga transportada", b: [
      { p: `La autoridad competente, impedirá la circulación del vehículo cuando se determine el exceso de personas o de carga, hasta tanto sean transferidas las personas o liberada la carga excedente, sin perjuicio de la aplicación de la sanción correspondiente.` }
    ]},
    { t: "art", n: 179, ep: "Suspensión de la licencia o título profesional de conducir", b: [
      { p: `Serán sancionados o sancionadas con suspensión de la licencia o título profesional:` },
      { lv: [
        [0, `Por el término de tres (3) meses, quien conduzca vehículos de un tipo distinto al autorizado por su licencia.`],
        [0, `Por el término de seis (6) meses:`],
        [1, `a. Los conductores y las conductoras con licencia de primer, segundo o tercer grado, que conduzcan vehículos correspondientes a dichas licencias, en condiciones que pongan en peligro la seguridad del tránsito.`],
        [1, `b. Los conductores y las conductoras que hayan acumulado cinco (5) infracciones en un período de doce (12) meses.`],
        [0, `Por el término de doce (12) meses:`],
        [1, `a. Los conductores y las conductoras con licencia de cuarto o quinto grado o título profesional que conduzcan vehículos correspondientes a dichas licencias, en condiciones que pongan en peligro la seguridad del tránsito.`],
        [1, `b. Los conductores y las conductoras que en caso de accidente de tránsito terrestre hayan producido lesiones gravísimas, de las tipificadas en el Código Penal y que hayan sido declarados o declaradas responsables por dicho accidente. En este caso, cuando el hecho se haya producido bajo influencia de la ingestión de bebidas alcohólicas, sustancias estupefacientes o psicotrópicas o por exceso de velocidad, la suspensión podrá dictarse hasta por tres (3) años contados a partir de la fecha de la sentencia definitivamente firme.`],
        [1, `c. Los conductores y las conductoras que tengan más de cinco (5) procedimientos acumulados en uno o más expedientes por infracción, en sede judicial.`],
        [1, `d. Los conductores y las conductoras que hayan acumulado tres (3) sanciones por conducir vehículos a exceso de velocidad o bajo influencia de bebidas alcohólicas o de sustancias estupefacientes o psicotrópicas.`],
        [0, `Por un término de tres (3) años:`],
        [1, `a. Los conductores y las conductoras que en un término de doce (12) meses hayan acumulado al menos dos (2) notas de suspensión.`],
        [1, `b. Los conductores y las conductoras que en caso de accidente hayan producido lesiones culposas graves de las tipificadas en el Código Penal y hayan sido declarados o declaradas responsables por dicho accidente.`],
        [0, `Por el término de cinco (5) años, a los conductores o las conductoras que en caso de accidentes donde tenga lugar el fallecimiento de personas, hayan sido declarados o declaradas responsables por dicho accidente. No obstante, cuando el hecho se haya producido bajo influencia de bebidas alcohólicas, sustancias estupefacientes y psicotrópicas o por exceso de velocidad, le será revocada la licencia y quedará inhabilitado por diez (10) años para obtener nueva licencia.`]
      ]},
      { p: `En el caso del numeral 2, literal b) y numeral 3, literal a), de este artículo, cuando el conductor o la conductora haya cumplido las dos (2) terceras partes de la sanción y dentro de este lapso haya realizado un curso sobre las normas de tránsito y transporte terrestre, con un mínimo de treinta (30) horas de duración, se le conmutará el resto de la sanción y la licencia o el título profesional recobrará su vigencia.` },
      { p: `La autoridad administrativa del transporte terrestre incorporará la decisión al Registro Nacional de Vehículos y de Conductores y Conductoras. Las formalidades a seguir con ocasión de la suspensión de licencias de conducir o de los títulos profesionales serán establecidas en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 180, ep: "Retención de la licencia o título profesional de conducir", b: [
      { p: `La licencia o el título profesional de conducir, sólo podrán ser retenidos en caso de decisión definitiva que acuerde la revocatoria. La decisión se notificará al Registro Nacional de Vehículos y de Conductores y Conductoras.` },
      { p: `En caso de suspensión, la decisión se incorporará al Registro Nacional de Vehículos y de Conductores y Conductoras, y se dejará constancia mediante nota que se estampará en la propia licencia o título profesional o por otros medios que determine el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 181, ep: "Casos de retención de los vehículos", b: [
      { p: `Se procederá a la retención de los vehículos por parte de las autoridades competentes del transporte terrestre, en sus respectivas circunscripciones, cuando se verifiquen los siguientes supuestos:` },
      { ol: [
        `Cuando el vehículo circule en condiciones evidentes de inseguridad y mal funcionamiento.`,
        `Cuando el conductor o la conductora no porte documento alguno que permita demostrar la propiedad del vehículo.`,
        `Cuando el vehículo circule sin sus correspondientes placas identificadoras, salvo que su conductor o conductora porte el permiso provisional de circulación previsto en el Reglamento de esta Ley, expedido por el Instituto Nacional de Transporte Terrestre.`,
        `Cuando el vehículo se encuentre actualmente involucrado en accidentes de tránsito terrestre con personas lesionadas o fallecidas.`,
        `Cuando se demuestre la falsedad de los documentos de registro o de los seriales de identificación del vehículo.`,
        `En los demás casos que señale la ley.`
      ]},
      { p: `En el caso del numeral 2 de este artículo, la autoridad deberá hacer entrega del mismo al momento de subsanarse la falta, sin perjuicio de la multa a que haya lugar. En el caso del numeral 1, la autoridad entregará el vehículo al propietario o a la propietaria al momento de disponer de una grúa, a los fines de ser trasladado, bien al lugar que éste estime conveniente o bien a talleres de reparación que subsanen la falla, en cuyo caso el propietario o la propietaria quedará sujeto a presentación y revisión del vehículo en la oportunidad que se fije. En el caso del numeral 4, el vehículo será entregado a su propietario o propietaria previa autorización del Fiscal del Ministerio Público que conozca del hecho, y cuando se trate del supuesto previsto en el numeral 5, las autoridades entregarán el vehículo a su propietario o propietaria una vez cumplido con los trámites correspondientes que demuestren la autenticidad de los documentos, en un lapso que no exceda de cinco (5) días hábiles.` }
    ]},
    { t: "art", n: 182, ep: "Extralimitación de funciones", b: [
      { p: `A los efectos del artículo anterior, la extralimitación y el abuso de poder de los funcionarios o funcionarias en el ejercicio de sus funciones, acarreará responsabilidad civil, administrativa y penal de acuerdo a la ley.` }
    ]},
    { t: "art", n: 183, ep: "Sanción por infracción en la instalación de vallas publicitarias", b: [
      { p: `En el caso de instalación de vallas, carteles o anuncios publicitarios fijos, en movimiento y sobre vehículos, que no cumplan con las autorizaciones respectivas establecidas en esta Ley y con la normativa técnica en cuanto a dimensiones y características previstas en el Reglamento de esta Ley, las personas naturales o jurídicas serán sancionadas con multa de quinientas Unidades Tributarias (500 U.T.) a mil Unidades Tributarias (1.000 U.T.).` },
      { p: `La autoridad administrativa competente removerá y trasladará el medio publicitario que contravenga las disposiciones de la ley y rescindirá el permiso respectivo. Los costos ocasionados por la remoción y traslado de los medios indicados en este artículo serán sufragados por el infractor.` },
      { p: `Serán solidariamente responsables aquellas personas naturales o jurídicas que contraten servicios de publicidad que incumplan con lo dispuesto en el presente artículo.` }
    ]},
    { t: "art", n: 184, ep: "Sanción por avisos publicitarios en vehículos de transporte", b: [
      { p: `En el caso de instalación de avisos publicitarios en vehículos destinados al servicio de transporte terrestre público o privado de personas y de carga, que no cumplan con las normas respectivas, establecidas en esta Ley y su Reglamento, las empresas publicitarias responsables serán sancionadas con multa de quinientas Unidades Tributarias (500 U.T.) a mil Unidades Tributarias (1.000 U.T.) de acuerdo a la siguiente escala:` },
      { ol: [
        `Por colocar la publicidad cubriendo la totalidad de la unidad, para el caso de transportes de personas, público, modalidad colectivo o privado, mil Unidades Tributarias (1.000 U.T.).`,
        `Por colocar la publicidad cubriendo la totalidad del transporte terrestre público, modalidad individual, ochocientas Unidades Tributarias (800 U.T.).`,
        `Por exceder las áreas publicitarias permitidas por el Reglamento de esta Ley, quinientas Unidades Tributarias (500 U.T.).`,
        `Por no colocar mensajes educativos y de seguridad vial en los vehículos de transporte terrestre público, privado y de carga, de acuerdo con lo establecido en el Reglamento de esta Ley, quinientas Unidades Tributarias (500 U.T.).`
      ]},
      { p: `La autoridad administrativa competente, removerá del vehículo el medio publicitario y rescindirá el permiso respectivo. Los costos generados serán sufragados por el infractor.` },
      { p: `Serán solidariamente responsables aquellas personas naturales o jurídicas que contraten servicios de publicidad que incumplan con lo dispuesto en el presente artículo.` }
    ]},
    { t: "art", n: 185, ep: "Prescripción de las infracciones", b: [
      { p: `Las multas establecidas por infracciones a las normas de transporte terrestre prescribirán a los cinco (5) años contados a partir de la notificación del sancionado o sancionada, de la decisión que pone fin al proceso. Igual lapso de prescripción tendrá la acción del Estado para exigir responsabilidad por las infracciones indicadas a partir de la fecha de su comisión.` }
    ]},
    { t: "art", n: 186, ep: "Sanciones e infracciones en materia de infraestructura vial", b: [
      { p: `Sin perjuicio de las sanciones establecidas en los contratos de concesión, los concesionarios o los administradores, que participan en la explotación y aprovechamiento de las vías, serán objeto de sanciones hasta el cinco por ciento (5%) de sus ingresos brutos, en los doce (12) meses anteriores al mes de la infracción, por la comisión de cualesquiera de los hechos siguientes:` },
      { ol: [
        `El incumplimiento de suministrar al ministerio del poder popular con competencia en materia de transporte terrestre o a la autoridad regional o local que corresponda, la información que se le solicite, en la oportunidad y en la forma en que hubiere sido requerida.`,
        `La negativa a permitir las verificaciones e inspecciones que acuerde la autoridad competente o la obstrucción a su realización.`
      ]}
    ]},
    { t: "art", n: 187, ep: "Sanciones e infracciones en materia de terminales", b: [
      { p: `Sin perjuicio de las sanciones establecidas en esta Ley, las personas jurídicas responsables de la operación, administración y mantenimiento de los terminales públicos y privados, serán objeto de sanciones de cien Unidades Tributarias (100 U.T.) a quinientas Unidades Tributarias (500 U.T.), y el Reglamento de esta Ley, establecerá la sanción según el flujo de transporte terrestre público autorizado para la clasificación de los terminales de pasajeros y pasajeras, por la comisión de cualesquiera de los hechos siguientes:` },
      { ol: [
        `La puesta en servicio del terminal sin la licencia de operación.`,
        `El incumplimiento reiterado del deber de suministrar a la autoridad competente la información que ésta solicite, en la oportunidad y en la forma en que hubiere sido solicitada.`,
        `La negativa a permitir las verificaciones e inspecciones que acuerde la autoridad competente o la obstrucción a su realización.`,
        `El incumplimiento de lo establecido en los permisos correspondientes de servicio conexo, en cuanto a los horarios de salida y tiempo de toque intermedio en los terminales.`
      ]},
      { p: `En el caso del numeral 1 si no han transcurrido los doce (12) meses referidos en el artículo 186, la sanción será de quinientas Unidades Tributarias (500 U.T.) a mil Unidades Tributarias (1.000 U.T.).` }
    ]},
    { t: "art", n: 188, ep: "Lapso para pagar las multas", b: [
      { p: `Las multas a que se refiere esta Ley deberán ser pagadas en la respectiva oficina receptora de fondos, dentro de los treinta (30) días hábiles siguientes contados a partir de la notificación. Vencido dicho plazo se causarán intereses de mora, sin necesidad de requerimiento previo de las autoridades administrativas del transporte terrestre, desde la fecha de su exigibilidad hasta la extinción total de la deuda.` }
    ]},
    { t: "art", n: 189, ep: "Juicio ejecutivo", b: [
      { p: `Si el sancionado o la sancionada no pagare la multa dentro del plazo indicado en el artículo anterior, las autoridades administrativas de transporte terrestre, a través del órgano competente, iniciarán de inmediato el juicio ejecutivo correspondiente para hacer efectivo el crédito, siguiéndose el procedimiento especial de la vía ejecutiva previsto en el Código de Procedimiento Civil. Las planillas de multas impuestas tienen el carácter de títulos ejecutivos.` }
    ]},
    { t: "art", n: 190, ep: "Restricciones de los trámites en la materia", b: [
      { p: `Los trámites ante las autoridades administrativas de transporte terrestre, sólo podrán realizarse previa cancelación de las multas pendientes y los derechos correspondientes, salvo que con ocasión del ejercicio de algún recurso se hayan suspendido los efectos del acto administrativo que dio lugar a la imposición de la multa.` }
    ]},
    { t: "art", n: 191, ep: "Procedimiento para aplicación de multas", b: [
      { p: `El procedimiento administrativo para la aplicación de las multas impuestas por las infracciones establecidas en este título, será el previsto en esta Ley para la aplicación de multas por infracciones de tránsito.` }
    ]},
    { t: "cap", num: "II", nombre: "De la Responsabilidad Civil por Accidente de Tránsito" },
    { t: "art", n: 192, ep: "Reparación de daños", b: [
      { p: `El conductor o la conductora, o el propietario o la propietaria del vehículo y su empresa aseguradora, están solidariamente obligados u obligadas a reparar todo daño que se cause con motivo de la circulación del vehículo, a menos que se pruebe que el daño proviene de un hecho de la víctima, o de un tercero que haga inevitable el daño; o que el accidente se hubiese producido por caso fortuito o fuerza mayor. Cuando el hecho de la víctima o del tercero haya contribuido a causar el daño, se aplicará lo establecido en el Código Civil. En caso de colisión entre vehículos, se presume, salvo prueba en contrario, que los conductores o las conductoras tienen igual responsabilidad civil por los daños causados.` }
    ]},
    { t: "art", n: 193, ep: "Límite de responsabilidad de los propietarios o propietarias de los vehículos", b: [
      { p: `Los propietarios o propietarias no serán responsables de los daños causados por sus vehículos cuando hayan sido privados de su posesión como consecuencia de hurto, robo o apropiación indebida.` }
    ]},
    { t: "art", n: 194, ep: "Accidentes de tránsito bajo los efectos del alcohol y otras sustancias", b: [
      { p: `Se presume, salvo prueba en contrario, que el conductor o la conductora es responsable de un accidente de tránsito cuando al ocurrir éste, se encuentre bajo los efectos de bebidas alcohólicas, de sustancias estupefacientes y psicotrópicas, o conduzca a exceso de velocidad. Al conductor o conductora se le practicará el examen toxicológico correspondiente, el cual podrá realizarse a través de pruebas e instrumentos científicos por parte de las autoridades competentes del transporte terrestre al momento de levantar el accidente. Los mecanismos e instrumentos para la práctica del examen, serán desarrollados en el Reglamento de esta Ley.` }
    ]},
    { t: "art", n: 195, ep: "Denuncias por incumplimiento del seguro de responsabilidad civil", b: [
      { p: `El Instituto Nacional de Transporte Terrestre informará a la Superintendencia de Seguros las denuncias contra aquellas empresas de seguro que incumplieren las obligaciones contraídas en las pólizas de responsabilidad civil de vehículos o condicionen la contratación de las pólizas, con el objeto de que se les apliquen las sanciones o medidas administrativas contempladas en la ley, sin menoscabo de la acción que pueda tener quien contrata contra la empresa directamente.` }
    ]},
    { t: "art", n: 196, ep: "Prescripción de las acciones civiles", b: [
      { p: `Las acciones civiles a que se refiere esta Ley para exigir la reparación de todo daño prescribirán a los doce (12) meses de sucedido el accidente. La acción de repetición a que se contrae el artículo anterior prescribirá en igual término, a partir del pago de la indemnización correspondiente.` }
    ]},
    { t: "art", n: 197, ep: "Disposiciones especiales", b: [
      { p: `El Ejecutivo Nacional podrá dictar disposiciones especiales sobre la garantía de responsabilidad civil que juzgue conveniente establecer a los propietarios y las propietarias o los conductores y las conductoras de vehículos con matrícula extranjera.` }
    ]},
    { t: "titulo", num: "VIII", nombre: "De los Procedimientos" },
    { t: "cap", num: "I", nombre: "Del Procedimiento Administrativo por Infracciones" },
    { t: "art", n: 198, ep: "Establecimiento de la responsabilidad administrativa", b: [
      { p: `La autoridad competente, en su respectiva jurisdicción, establecerá la responsabilidad administrativa por infracciones en materia de transporte terrestre, incluso cuando se causen daños a personas y bienes, a la República, a los estados o a los municipios.` }
    ]},
    { t: "art", n: 199, ep: "Procedimiento", b: [
      { p: `El inicio, la sustanciación y resolución de las actuaciones administrativas a que diere lugar la aplicación de esta Ley, se ajustarán a las disposiciones establecidas en su texto, y en la ley que regula los procedimientos administrativos.` }
    ]},
    { t: "art", n: 200, ep: "Daños materiales", b: [
      { p: `Cuando un accidente de tránsito terrestre produzca daños materiales, la autoridad que conozca del mismo debe:` },
      { ol: [
        `Verificar si los vehículos reúnen las condiciones de seguridad exigidas en esta Ley y cualesquiera otras normas que regulen la materia.`,
        `Levantar el croquis del accidente, hacer una relación de los daños sufridos por los vehículos o por cualquiera otra propiedad, y formar el expediente administrativo del caso.`,
        `Ordenar el avalúo de los daños causados, que se hará por un solo perito designado por la autoridad administrativa competente del transporte terrestre.`,
        `Realizar las experticias necesarias para determinar si los conductores implicados o las conductoras implicadas en el accidente de tránsito se encuentran bajo los efectos del alcohol o de sustancias estupefacientes o psicotrópicas.`
      ]}
    ]},
    { t: "art", n: 201, ep: "Inicio del procedimiento de multa", b: [
      { p: `El acto de imposición de la sanción deberá contener la citación del presunto infractor o infractora, para que comparezca al tercer día hábil siguiente ante la autoridad competente que la practicó. Si la citación personal no fuere posible, será suficiente que la boleta sea entregada en la dirección que consta en el Registro Nacional de Vehículos y de Conductores y Conductoras, lo cual se comprobará con el recibo firmado por quien la haya recibido. En este caso, el lapso para la comparecencia comenzará a correr una vez que conste en el expediente respectivo las diligencias practicadas.` }
    ]},
    { t: "art", n: 202, ep: "Acto de comparecencia", b: [
      { p: `A la hora y fecha fijada en la boleta de citación, el presunto infractor o infractora deberá comparecer, a los efectos de presentar su descargo en forma oral o escrita, o admitir la infracción imputada.` }
    ]},
    { t: "art", n: 203, ep: "Conclusión anticipada del procedimiento por pago de multa", b: [
      { p: `Cuando en el acto de comparecencia el presunto infractor o presunta infractora compruebe el pago de la multa o admita la infracción imputada y proceda a su pago, se dará por concluido el procedimiento administrativo.` }
    ]},
    { t: "art", n: 204, ep: "Lapso probatorio", b: [
      { p: `Si en el acto de comparecencia el presunto infractor o presunta infractora impugna la sanción impuesta, se abrirá un lapso probatorio de cinco (5) días hábiles para la promoción y evacuación de pruebas.` }
    ]},
    { t: "art", n: 205, ep: "Decisión", b: [
      { p: `Dentro de los cinco (5) días hábiles siguientes al acto de comparecencia o del vencimiento del lapso previsto en el artículo anterior, la autoridad administrativa competente dictará su decisión, confirmando o revocando la sanción impuesta.` }
    ]},
    { t: "art", n: 206, ep: "Recursos contra la decisión", b: [
      { p: `Contra las decisiones que impongan una sanción, podrá interponerse el recurso de reconsideración dentro de los quince (15) días hábiles siguientes o acudir directamente a la vía jurisdiccional, dentro de los treinta (30) días hábiles siguientes. Si es ejercido el recurso de reconsideración, deberá agotarse íntegramente la vía administrativa para poder acudir a la vía jurisdiccional.` }
    ]},
    { t: "art", n: 207, ep: "Responsabilidad del funcionario o funcionaria por decisión extemporánea", b: [
      { p: `La falta de decisión oportuna en los plazos previstos en el presente procedimiento, a excepción del recurso de reconsideración, acarreará la culminación del procedimiento administrativo, y la consecuente responsabilidad de los funcionarios o funcionarias involucrados conforme a la ley.` }
    ]},
    { t: "art", n: 208, ep: "Notificación de la decisión", b: [
      { p: `La decisión definitiva deberá ser notificada a su destinatario en caso de que este no se haya presentado al acto de comparecencia.` }
    ]},
    { t: "art", n: 209, ep: "Curso de orientación en la materia de educación y seguridad vial", b: [
      { p: `La autoridad del transporte terrestre que conozca de las infracciones cometidas por los conductores o las conductoras que hayan puesto en peligro la circulación del tránsito y la seguridad de las personas, según lo establecido en el Reglamento de esta Ley, sin perjuicio de la multa correspondiente, podrá disponer que asistan con carácter de obligatoriedad a un curso de orientación en materia de educación y seguridad vial, que no excederá de treinta (30) horas, ni podrá dictarse en días laborables.` }
    ]},
    { t: "art", n: 210, ep: "Obligación de remisión de estadística sobre accidentes de tránsito", b: [
      { p: `Las autoridades competentes que conozcan y actúen en accidentes de tránsito terrestre, están obligadas a remitir la información al Sistema Nacional de Registro de Transporte Terrestre, el cual llevará el registro estadístico nacional de accidentes de tránsito.` }
    ]},
    { t: "art", n: 211, ep: "Protección de los derechos del usuario y de la usuaria", b: [
      { p: `En los casos de incumplimiento de las obligaciones derivadas de la prestación del servicio de transporte terrestre u otras que afecten los derechos e intereses de los usuarios y las usuarias, distintas a las actuaciones por accidentes o infracciones, se aplicará lo dispuesto en la Ley de Protección al Consumidor y al Usuario.` }
    ]},
    { t: "cap", num: "II", nombre: "Del Procedimiento Civil" },
    { t: "art", n: 212, ep: "Acción civil", b: [
      { p: `El procedimiento para determinar la responsabilidad civil derivada de accidentes de tránsito en los cuales se hayan ocasionado daños a personas o cosas, será el establecido para el juicio oral en el Código de Procedimiento Civil, sin perjuicio de lo dispuesto en el Código Orgánico Procesal sobre la reparación de daños.` },
      { p: `La acción se interpondrá por ante el Tribunal competente según la cuantía del daño, en la circunscripción donde haya ocurrido el hecho.` }
    ]},
    { t: "cap", num: "III", nombre: "Del Procedimiento Penal" },
    { t: "art", n: 213, ep: "Remisión al Código Orgánico Procesal Penal", b: [
      { p: `Todo procedimiento penal que derive de accidentes de transporte terrestre, se desarrollará conforme con lo establecido en el Código Orgánico Procesal Penal.` }
    ]},
    { t: "art", n: 214, ep: "Autoridad administrativa", b: [
      { p: `El Cuerpo Técnico de Vigilancia del Transporte Terrestre apoyará a la autoridad competente, con carácter de policía de investigación penal, científica y criminalística para practicar, bajo la dirección del Ministerio Público, las diligencias conducentes a la determinación de los hechos punibles, sus causas y la identificación de sus autores y partícipes, con ocasión de los accidentes de tránsito terrestre donde resulten personas lesionadas y fallecidas.` }
    ]},
    { t: "art", n: 215, ep: "Investigación técnica de los accidentes de transporte terrestre", b: [
      { p: `A los efectos de la investigación técnica, científica y criminalística de los accidentes de transporte terrestre, el Cuerpo Técnico de Vigilancia del Transporte Terrestre creará y mantendrá con carácter nacional, los laboratorios y equipos necesarios para el cabal desempeño de sus funciones.` }
    ]},
    { t: "sec", nombre: "Disposición Derogatoria" },
    { t: "disp", id: "derogatoria", label: "Única", nombre: "Disposición Derogatoria Única", b: [
      { p: `Se deroga el Decreto con Fuerza de Ley de Tránsito y Transporte Terrestre, publicado en la Gaceta Oficial de la República Bolivariana de Venezuela N° 37.332 de fecha 26 de Noviembre de 2001.` }
    ]},
    { t: "sec", nombre: "Disposiciones Transitorias" },
    { t: "disp", id: "transitoria-1", label: "Primera", nombre: "Disposición Transitoria Primera", b: [
      { p: `La implantación del Sistema Nacional de Registro del Transporte Terrestre entrará en vigencia por tipo de registro y por estado conforme lo resuelva el Directorio del Instituto Nacional de Transporte Terrestre, previéndose un lapso de veinticuatro (24) meses para su total instauración, contado a partir de la promulgación de esta Ley. Igualmente la aplicación de las sanciones establecidas como consecuencia del retardo injustificado de los trámites que se realicen ante los funcionarios o las funcionarias del transporte terrestre atinentes al Sistema de Registros, será procedente en las entidades federales donde haya entrado en funcionamiento el referido Sistema, conforme a las decisiones del Directorio del Instituto Nacional de Transporte Terrestre.` }
    ]},
    { t: "disp", id: "transitoria-2", label: "Segunda", nombre: "Disposición Transitoria Segunda", b: [
      { p: `Los operadores u operadoras sujetos a la obligación de instalar en sus vehículos los dispositivos de control y registro de velocidad, tendrán un lapso de adecuación de ciento ochenta (180) días, a partir de la entrada en vigencia de la norma que determine el tipo, condiciones y requisitos de funcionamiento e instalación, norma esta que deberá ser dictada por el Instituto Nacional de Transporte Terrestre en un lapso de treinta (30) días a partir de la entrada en vigencia de la presente Ley.` },
      { p: `Para los casos de los vehículos que tengan el dispositivo instalado de fábrica y se encuentre en servicio, sus propietarios o propietarias deberán adecuarlo y ponerlo en funcionamiento en un lapso de ciento veinte (120) días a partir de la entrada en vigencia de la norma a que se refiere el encabezamiento de esta disposición.` }
    ]},
    { t: "disp", id: "transitoria-3", label: "Tercera", nombre: "Disposición Transitoria Tercera", b: [
      { p: `Las personas naturales y jurídicas dedicadas a la prestación del servicio de transporte terrestre, incluyendo sus servicios conexos, en cuanto a los permisos respectivos, tendrán un lapso de actualización de ciento ochenta (180) días, a partir de la entrada en vigencia de esta Ley, dejando a salvo los derechos en cuanto al término de vigencia otorgado en las certificaciones de prestación de servicio.` }
    ]},
    { t: "disp", id: "transitoria-4", label: "Cuarta", nombre: "Disposición Transitoria Cuarta", b: [
      { p: `Las personas jurídicas que prestan servicio de transporte terrestre público de personas en la modalidad de cuatro (4) o cinco (5) puestos en rutas interurbanas y posean certificación de prestación de servicio vigente, autorizada por el Instituto Nacional de Transporte Terrestre, tienen un lapso de cuatro (4) años a partir de la entrada en vigencia de esta Ley, para realizar el mejoramiento del servicio con vehículos nuevos o usados, no mayores de cinco (5) años y capacidad de cuatro (4) o cinco (5) puestos, de conformidad con las Normas del Sistema Nacional de Calidad o de unidades cuya tipología corresponda a rutas interurbanas que cumplan con las demás disposiciones previstas en el Reglamento de esta Ley.` }
    ]},
    { t: "disp", id: "transitoria-5", label: "Quinta", nombre: "Disposición Transitoria Quinta", b: [
      { p: `El Ejecutivo Nacional a través del Instituto Nacional de Transporte Terrestre dotará al Cuerpo Técnico de Vigilancia del Transporte Terrestre de los equipos de laboratorios para la investigación técnica de los accidentes de transporte terrestre en un lapso no mayor de noventa (90) días, contados a partir de la entrada en vigencia de esta Ley.` }
    ]},
    { t: "disp", id: "transitoria-6", label: "Sexta", nombre: "Disposición Transitoria Sexta", b: [
      { p: `El Instituto Nacional de Tránsito y Transporte Terrestre, una vez publicada esta Ley, pasará a denominarse Instituto Nacional de Transporte Terrestre, tal como está previsto en su artículo 22.` },
      { p: `En trámites rutinarios, el Instituto Nacional de Transporte Terrestre agotará el inventario documental de papelería elaborada para el Instituto Nacional de Tránsito y Transporte Terrestre; su renovación se hará progresivamente con la denominación Instituto Nacional de Transporte Terrestre, en un plazo que no se extenderá más allá de cinco (5) años.` }
    ]},
    { t: "disp", id: "transitoria-7", label: "Séptima", nombre: "Disposición Transitoria Séptima", b: [
      { p: `El ministerio del poder popular con competencia en materia de salud, pasará a ser el órgano encargado de la expedición del Certificado Médico de Salud Integral para conducir tal como está previsto en el artículo 63, y dicho ministerio dispondrá de un lapso no mayor de dos (2) años para realizar la implementación de la prestación de este servicio, a partir de la entrada en vigencia de esta Ley. De igual manera, durante este período de transición, la expedición de los Certificados Médicos de Salud Integral para conducir estará a cargo de los colegios médicos regionales en coordinación con el ministerio del poder popular con competencia en materia de salud.` }
    ]},
    { t: "disp", id: "transitoria-8", label: "Octava", nombre: "Disposición Transitoria Octava", b: [
      { p: `En un lapso de cuatro (4) años, contados a partir de la publicación de esta Ley, el Instituto Nacional de Transporte Terrestre coordinará retirar de la circulación y del Registro Nacional de Vehículos y de Conductores y Conductoras, las unidades de transporte terrestre público de pasajeros y pasajeras, que previa revisión técnica, mecánica y física no ofrezcan al usuario y la usuaria un servicio cómodo, higiénico, confortable y seguro.` }
    ]},
    { t: "sec", nombre: "Disposición Final" },
    { t: "disp", id: "final", label: "Única", nombre: "Disposición Final Única", b: [
      { p: `La presente Ley entrará en vigencia a partir de la fecha de su publicación en la Gaceta Oficial de la República Bolivariana de Venezuela.` }
    ]},
    { t: "cierre", b: [
      { p: `Dada, firmada y sellada en el Palacio Federal Legislativo, sede de la Asamblea Nacional, en Caracas, a los ocho días del mes de julio de dos mil ocho. Año 198° de la Independencia y 149° de la Federación.` },
      { p: `Palacio de Miraflores, en Caracas, a los treinta y un días del mes de julio de dos mil ocho. Años 198° de la Independencia, 149° de la Federación y 10° de Revolución Bolivariana.` }
    ]}
  ]
};